sparql_query:
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?place ?healthConcern
WHERE {
  ?place rdf:type kwg-ont:Region .
  OPTIONAL { ?place kwg-ont:sfWithin ?region . }
  OPTIONAL { ?place geo:hasGeometry ?geometry . }
  OPTIONAL { ?place sosa:hosts ?healthCareFacility . }
  OPTIONAL { ?healthCareFacility rdf:type kwg-ont:HealthCareFacility .
             ?healthCareFacility kwg-ont:helipadAvailability ?helipadAvailability .
             BIND(CONCAT("Helipad Availability - ", STR(?helipadAvailability)) AS ?healthConcern) }
  OPTIONAL { ?healthCareFacility rdf:type kwg-ont:HealthCareFacility .
             ?healthCareFacility kwg-ont:hospitalStatus ?hospitalStatus .
             BIND(CONCAT("Hospital Status - ", STR(?hospitalStatus)) AS ?healthConcern) }
  OPTIONAL { ?healthCareFacility rdf:type kwg-ont:HealthCareFacility .
             ?healthCareFacility kwg-ont:hospitalType ?hospitalType .
             BIND(CONCAT("Hospital Type - ", STR(?hospitalType)) AS ?healthConcern) }
}

PREFIX : <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sf: <http://www.opengis.net/ont/sf#>
PREFIX c4o: <http://purl.org/spar/c4o/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xml: <http://www.w3.org/XML/1998/namespace>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX core: <http://purl.org/vocab/frbr/core/>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX irdr: <http://www.knowwheregraph.org/ontologies/hazard/IRDR/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX qudt: <http://qudt.org/1.1/schema/qudt#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX terms: <http://purl.org/dc/terms/>
PREFIX schema: <http://schema.org/>
PREFIX geocode: <http://ld.iospress.nl/rdf/geocode/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX iospress: <http://ld.iospress.nl/rdf/ontology/>
PREFIX wgs84_pos: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX kwg-r: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?geographicPlace ?demographicAttribute
WHERE {
  {
    # Query for population data
    ?geographicPlace a usgs:PopulatedPlace ;
                     rdfs:label ?placeName .
    ?observationCollection a kwg-ont:CensusACS5YearEstimatesObservationCollection ;
                           sosa:hasMember ?observation .
    ?observation sosa:observedProperty kwgr:censusObservableProperty.totalPopulation ;
                  sosa:resultTime ?time ;
                  sosa:hasFeatureOfInterest ?geographicPlace ;
                  sosa:hasSimpleResult ?populationValue .

    BIND (CONCAT("Total Population in ", ?placeName, " is ", ?populationValue) AS ?demographicAttribute)
  }
  UNION
  {
    # Query for household units data
    ?geographicPlace a usgs:PopulatedPlace ;
                     rdfs:label ?placeName .
    ?observationCollection a kwg-ont:CensusACS5YearEstimatesObservationCollection ;
                           sosa:hasMember ?observation .
    ?observation sosa:observedProperty kwgr:censusObservableProperty.householdUnits ;
                  sosa:resultTime ?time ;
                  sosa:hasFeatureOfInterest ?geographicPlace ;
                  sosa:hasSimpleResult ?householdUnitsValue .

    BIND (CONCAT("Household Units in ", ?placeName, " is ", ?householdUnitsValue) AS ?demographicAttribute)
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardName
WHERE {
  ?hazard a kwg-ont:Hazard ;
          rdfs:label ?hazardName .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardAttribute ?details
WHERE {
  {
    SELECT ?hazardAttribute (GROUP_CONCAT(DISTINCT ?propertyLabel; separator=", ") AS ?details)
    WHERE {
      {
        ?hazardAttribute rdf:type kwg-ont:Hazard .
        OPTIONAL { ?hazardAttribute rdfs:label ?hazardName . }
        FILTER NOT EXISTS { ?hazardAttribute rdfs:subClassOf* kwg-ont:NOAAHazardEvent . }
      }
      UNION
      {
        ?hazardAttribute rdf:type kwg-ont:NOAAHazard .
        OPTIONAL { ?hazardAttribute rdfs:label ?hazardName . }
      }
      UNION
      {
        ?hazardAttribute rdf:type kwg-ont:NOAAHazardEvent .
        OPTIONAL { ?hazardAttribute rdfs:label ?hazardName . }
      }
      UNION
      {
        ?hazardAttribute rdf:type kwg-ont:DroughtZone .
        OPTIONAL { ?hazardAttribute rdfs:label ?hazardName . }
      }
      UNION
      {
        ?hazardAttribute rdf:type kwg-ont:Earthquake .
        OPTIONAL { ?hazardAttribute rdfs:label ?hazardName . }
      }
      UNION
      {
        ?hazardAttribute rdf:type kwg-ont:SmokePlumeSnapshot .
        OPTIONAL { ?hazardAttribute rdfs:label ?hazardName . }
      }
      UNION
      {
        ?hazardAttribute rdf:type kwg-ont:MTBSFire .
        OPTIONAL { ?hazardAttribute rdfs:label ?hazardName . }
      }
      UNION
      {
        ?hazardAttribute rdf:type kwg-ont:NIFCFire .
        OPTIONAL { ?hazardAttribute rdfs:label ?hazardName . }
      }

      # Collect all properties related to the hazard attribute
      OPTIONAL { ?hazardAttribute ?property ?value . }
    }
    GROUP BY ?hazardAttribute
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardAttribute ?details
WHERE {
  {
    SELECT ?hazardAttribute (GROUP_CONCAT(DISTINCT ?propertyLabel; separator=", ") AS ?details) WHERE {
      VALUES (?hazardClass) {(kwg-ont:NOAAAstronomicalLowTide kwg-ont:NOAAAvalanche kwg-ont:NOAABlizzard kwg-ont:NOAACoastalFlood kwg-ont:NOAAColdWindChill kwg-ont:NOAADebrisFlow kwg-ont:NOAADenseFog kwg-ont:NOAADenseSmoke kwg-ont:NOAADrought kwg-ont:NOAADustDevil kwg-ont:NOAADustStorm kwg-ont:NOAAExcessiveHeat kwg-ont:NOAAExtremeColdWindChill kwg-ont:NOAAFlashFlood kwg-ont:NOAAFlood kwg-ont:NOAAFreezingFog kwg-ont:NOAAFrostFreeze kwg-ont:NOAAFunnelCloud kwg-ont:NOAAHail kwg-ont:NOAAHeat kwg-ont:NOAAHeavyRain kwg-ont:NOAAHeavySnow kwg-ont:NOAAHighSurf kwg-ont:NOAAHighWind kwg-ont:NOAAHurricane kwg-ont:NOAAIceStorm kwg-ont:NOAALake-EffectSnow kwg-ont:NOAALakeshoreFlood kwg-ont:NOAALightning kwg-ont:NOAAMarineHail kwg-ont:NOAAMarineHighWind kwg-ont:NOAAMarineHurricaneTyphoon kwg-ont:NOAAMarineStrongWind kwg-ont:NOAAMarineThunderstormWind kwg-ont:NOAAMarineTropicalDepression kwg-ont:NOAAMarineTropicalStorm kwg-ont:NOAARipCurrent kwg-ont:NOAASleet kwg-ont:NOAASneakerwave kwg-ont:NOAAStormSurgeTide kwg-ont:NOAAStrongWind kwg-ont:NOAAThunderstormWind kwg-ont:NOAATornado kwg-ont:NOAATropicalDepression kwg-ont:NOAATropicalStorm kwg-ont:NOAAWaterspout kwg-ont:NOAAWildfire kwg-ont:NOAAWinterStorm kwg-ont:NOAAWinterWeather)}
      ?hazardClass rdfs:subClassOf* ?hazardAttribute .
      OPTIONAL {?hazardAttribute rdfs:label ?propertyLabel .}
    }
    GROUP BY ?hazardAttribute
  }
  UNION
  {
    SELECT ?hazardAttribute (GROUP_CONCAT(DISTINCT ?propertyLabel; separator=", ") AS ?details) WHERE {
      VALUES (?hazardClass) {(kwg-ont:NOAAAstronomicalLowTide kwg-ont:NOAAAvalanche kwg-ont:NOAABlizzard kwg-ont:NOAACoastalFlood kwg-ont:NOAAColdWindChill kwg-ont:NOAADebrisFlow kwg-ont:NOAADenseFog kwg-ont:NOAADenseSmoke kwg-ont:NOAADrought kwg-ont:NOAADustDevil kwg-ont:NOAADustStorm kwg-ont:NOAAExcessiveHeat kwg-ont:NOAAExtremeColdWindChill kwg-ont:NOAAFlashFlood kwg-ont:NOAAFlood kwg-ont:NOAAFreezingFog kwg-ont:NOAAFrostFreeze kwg-ont:NOAAFunnelCloud kwg-ont:NOAAHail kwg-ont:NOAAHeat kwg-ont:NOAAHeavyRain kwg-ont:NOAAHeavySnow kwg-ont:NOAAHighSurf kwg-ont:NOAAHighWind kwg-ont:NOAAHurricane kwg-ont:NOAAIceStorm kwg-ont:NOAALake-EffectSnow kwg-ont:NOAALakeshoreFlood kwg-ont:NOAALightning kwg-ont:NOAAMarineHail kwg-ont:NOAAMarineHighWind kwg-ont:NOAAMarineHurricaneTyphoon kwg-ont:NOAAMarineStrongWind kwg-ont:NOAAMarineThunderstormWind kwg-ont:NOAAMarineTropicalDepression kwg-ont:NOAAMarineTropicalStorm kwg-ont:NOAARipCurrent kwg-ont:NOAASleet kwg-ont:NOAASneakerwave kwg-ont:NOAAStormSurgeTide kwg-ont:NOAAStrongWind kwg-ont:NOAAThunderstormWind kwg-ont:NOAATornado kwg-ont:NOAATropicalDepression kwg-ont:NOAATropicalStorm kwg-ont:NOAAWaterspout kwg-ont:NOAAWildfire kwg-ont:NOAAWinterStorm kwg-ont:NOAAWinterWeather)}
      ?hazardAttribute rdfs:subClassOf* ?hazardClass .
      OPTIONAL {?hazardAttribute rdfs:label ?propertyLabel .}
    }
    GROUP BY ?hazardAttribute
  }
}

