SELECT DISTINCT ?hazard ?hazardLabel ?hazardType ?hazardDetails
WHERE {
  {
    ?hazard rdf:type kwg-ont:Earthquake .
    OPTIONAL { ?hazard rdfs:label ?hazardLabel . }
    OPTIONAL { ?hazard rdf:type ?hazardType . }
    OPTIONAL { ?hazard skos:definition ?hazardDetails . }
  } UNION {
    ?hazard rdf:type kwg-ont:DroughtZone .
    OPTIONAL { ?hazard rdfs:label ?hazardLabel . }
    OPTIONAL { ?hazard rdf:type ?hazardType . }
    OPTIONAL { ?hazard skos:definition ?hazardDetails . }
  } UNION {
    ?hazard rdf:type kwg-ont:SmokePlumeSnapshot .
    OPTIONAL { ?hazard rdfs:label ?hazardLabel . }
    OPTIONAL { ?hazard rdf:type ?hazardType . }
    OPTIONAL { ?hazard skos:definition ?hazardDetails . }
