PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?impactFactorDetails
WHERE {
    ?hazardEvent a kwg-ont:NOAAHazardEvent .
    OPTIONAL { ?hazardEvent kwg-ont:hasSegment ?segment . }
    OPTIONAL { ?segment kwg-ont:endsAt ?fix . }
    OPTIONAL { ?fix geo:hasDefaultGeometry ?geometry . }
    OPTIONAL { ?geometry geo:asWKT ?wktLiteral . }
    BIND (CONCAT("Impact Factor Details for Hazard Event: ", STR(?hazardEvent), " Segment: ", COALESCE(STR(?segment), "N/A"), " Fix: ", COALESCE(STR(?fix), "N/A"), " Geometry WKT: ", COALESCE(STR(?wktLiteral), "N/A")) AS ?impactFactorDetails)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardAttribute ?damageImpactDetails ?temporalData
WHERE {
  # Hurricane-specific hazard attributes related to a geographical place
  ?hazard rdf:type kwg-ont:NOAAHurricane .
  OPTIONAL { ?hazard kwg-ont:affectedByInverse ?geographicalPlace . }
  OPTIONAL { ?hazard kwg-ont:hasSegment ?segment . }

  # Damage impact details
  OPTIONAL {
    ?impactObservationCollection sosa:hasMember ?impactObservation .
    ?impactObservation a kwg-ont:ImpactObservation ;
                        sosa:observedProperty ?damageImpactDetails .
  }
  OPTIONAL { ?hazard kwg-ont:episodeHasPart ?event . }

  # Temporal data
  OPTIONAL {
    ?temporalData a time:TemporalEntity .
    ?segment kwg-ont:startsFrom ?fixStarts .
    ?fixStarts time:hasBeginning ?startTime .
    BIND(?startTime AS ?temporalData)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard (GROUP_CONCAT(?propertyName ; separator=",") AS ?details) ?temporalScope
WHERE {
    {
        ?hazard rdf:type kwg-ont:Hazard .
        OPTIONAL { ?hazard time:hasTemporalDuration ?temporalScope .}
        # Get properties of Hazard and its subclasses
        VALUES (?superClass) {(kwg-ont:Earthquake) (kwg-ont:Fire) (kwg-ont:SmokePlumeSnapshot)}
        FILTER (?hazard rdf:type ?superClass)
        {
            SELECT DISTINCT * WHERE {
                { ?hazard a ?t . }
                UNION
                {
                    SELECT * WHERE {
                        ?p ?o ?hazard .
                        OPTIONAL { ?o rdfs:label ?propertyName . }
                        FILTER (isLiteral(?o))
                    }
                }
                FILTER (?superClass != kwg-ont:Fire)
            } GROUP_CONCAT(DISTINCT ?t AS ?details) ORDER BY ?details
        }
    }
}
GROUP BY ?hazard ?temporalScope
ORDER BY DESC(?temporalScope)

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT DISTINCT ?place ?name WHERE {
  { ?place rdfs:subClassOf kwg-ont:AdministrativeRegion . }
  UNION
  { ?place rdfs:subClassOf usgs:SurfaceWater . }
  UNION
  { ?place rdfs:subClassOf usgs:BuiltUpArea .}
  UNION
  { ?place rdfs:subClassOf usgs:Terrain . }
  OPTIONAL{?place rdfs:label ?name.}}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?healthConcern ?geographicalPlace WHERE {
    {
        SELECT DISTINCT ?healthConcern WHERE {
            ?concern rdfs:subClassOf kwg-ont:Hazard .
            ?concern a ?healthConcernType .
        }
    }
    UNION
    {
        SELECT DISTINCT ?observationProperty WHERE {
            ?property rdfs:subClassOf sosa:ObservableProperty .
            ?property a ?observationProperty .
        }
    }
    OPTIONAL {?concern geo:hasDefaultGeometry ?geometry .}
    OPTIONAL {?concern geo:hasGeometry ?geometry .}
    OPTIONAL {
        SELECT DISTINCT ?geographicalPlace WHERE {
            ?place rdfs:subClassOf kwg-ont:AdministrativeRegion .
            ?place a ?geographicalPlaceType .
        }
    }
    OPTIONAL {?concern kwg-ont:spatialRelation ?geographicalPlace .}
    OPTIONAL {?concern kwg-ont:sfWithin ?geographicalPlace .}
}

PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>

SELECT DISTINCT ?property
WHERE {
  {
    SELECT DISTINCT ?prop WHERE {
      ?class rdfs:subClassOf* kwg-ont:CensusObservableProperty .
      ?prop rdfs:domain ?class .
      FILTER (isLiteral(?prop))
    }
  } UNION {
    SELECT DISTINCT ?prop WHERE {
      ?class rdfs:subClassOf* kwg-ont:Region .
      ?prop rdfs:domain ?class .
      FILTER (isLiteral(?prop))
    }
  } UNION {
    SELECT DISTINCT ?prop WHERE {
      ?class rdfs:subClassOf* usgs:BuiltUpArea .
      ?prop rdfs:domain ?class .
      FILTER (isLiteral(?prop))
    }
  } UNION {
    SELECT DISTINCT ?prop WHERE {
      ?class rdfs:subClassOf* kwg-ont:Hospital .
      ?prop rdfs:domain ?class .
      FILTER (isLiteral(?prop))
    }
  } UNION {
    SELECT DISTINCT ?prop WHERE {
      ?class rdfs:subClassOf* geo:Feature .
      ?prop rdfs:domain ?class .
      FILTER (isLiteral(?prop))
    }
  } UNION {
    SELECT DISTINCT ?prop WHERE {
      ?class rdfs:subClassOf* kwg-ont:AdministrativeRegion .
      ?prop rdfs:domain ?class .
      FILTER (isLiteral(?prop))
    }
  }
}

PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardAttribute ?attributeName WHERE {
  {
    SELECT ?hazardAttribute ?attributeName WHERE {
      {
        # StormTrack-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:StormTrackObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:stormTrackObservableProperty"))
      } UNION {
        # StormTracklet-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:StormTrackletObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:stormTrackletObservableProperty"))
      } UNION {
        # Earthquake-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:EarthquakeObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:earthquakeObservableProperty"))
      } UNION {
        # Drought-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:DroughtIntensity . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:droughtObservableProperty"))
      } UNION {
        # Magnitude-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:MagnitudeObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:magnitudeObservableProperty"))
      } UNION {
        # Impact-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:ImpactObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:impactObservableProperty"))
      } UNION {
        # MTBS Fire-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:MTBSFireObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:mtbsFireObservableProperty"))
      } UNION {
        # NIFC Fire-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:NIFCFireObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:nifcFireObservableProperty"))
      } UNION {
        # Smoke Plume-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:SmokePlumeObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:smokePlumeObservableProperty"))
      } UNION {
        # Bluesky Wildfire-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:BlueskyWildfireObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:blueskyObservableProperty"))
      } UNION {
        # Vulnerability-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:VulnerabilityObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:vulnerabilityObservableProperty"))
      } UNION {
        # Soil Map Unit-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:SoilMapUnitObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:soilMapUnitObservableProperty"))
      } UNION {
        # Climate-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:ClimateObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:climateObservableProperty"))
      } UNION {
        # Census-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:CensusObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:censusObservableProperty"))
      } UNION {
        # Air Quality-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:AirPollutant . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:airQualityObservableProperty"))
      } UNION {
        # Cropland-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:CroplandObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:croplandObservableProperty"))
      } UNION {
        # Public Health-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:PublicHealthObservableProperty . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:publicHealthObservableProperty"))
      } UNION {
        # Road Segment-related attributes
        OPTIONAL { ?hazardAttribute rdfs:subClassOf kwg-ont:RoadType . }
        OPTIONAL { ?hazardAttribute rdfs:label ?attributeName . }
        FILTER(REGEX(str(?hazardAttribute), "kwgr:roadType"))
      }
    }
  }.
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardAttribute WHERE {
  ?floodHazard a kwg-ont:NOAAHazardEvent ;
              rdfs:subClassOf* kwg-ont:Flood .
  ?floodHazard sosa:observedProperty ?hazardAttribute .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?attribute WHERE {
  VALUES (?class) {(kwg-ont:AdministrativeRegion_0)
                   (kwg-ont:AdministrativeRegion_1)
                   (kwg-ont:AdministrativeRegion_2)
                   (kwg-ont:AdministrativeRegion_3)
                   (kwg-ont:AdministrativeRegion_4)
                   (kwg-ont:AdministrativeRegion_5)
                   (kwg-ont:AdministrativeRegion_6)}
  ?class rdfs:subClassOf* kwg-ont:Region.
  {
    SELECT DISTINCT ?attribute WHERE {
      ?class a ?type .
      FILTER(isBlank(?type))
    }
  } UNION
  {
    SELECT DISTINCT ?attribute WHERE {
      ?class kwg-ont:hasGeometry ?geometry .
      ?geometry geo:hasSerialization ?attribute .
    }
  } UNION
  {
    SELECT DISTINCT ?attribute WHERE {
      ?class a ?superclass .
      ?superclass rdfs:subClassOf* ?class .
      FILTER(isBlank(?superclass))
    }
  } UNION
  {
    SELECT DISTINCT ?attribute WHERE {
      ?class kwg-ont:sfWithin ?within .
      ?within rdfs:label ?attribute .
    }
  } UNION
  {
    SELECT DISTINCT ?attribute WHERE {
      ?class kwg-ont:spatialRelation ?relation .
      ?relation geo:hasDefaultGeometry ?geometry .
      ?geometry geo:asWKT ?attribute .
    }
  } UNION
  {
    SELECT DISTINCT ?attribute WHERE {
      ?class kwg-ont:hasRoadType ?type .
      ?type rdfs:label ?attribute .
    }
  } UNION
  {
    SELECT DISTINCT ?attribute WHERE {
      ?class a kwg-ont:RoadSegment .
      ?class kwg-ont:hasLength ?attribute .
    }
  } UNION
  {
    SELECT DISTINCT ?attribute WHERE {
      ?class a kwg-ont:AirQualitySite .
      ?class kwg-ont:cbsaCode ?attribute .
    }
  } UNION
  {
    SELECT DISTINCT ?attribute WHERE {
      ?class a kwg-ont:AirQualitySite .
      ?class kwg-ont:siteID ?attribute .
    }
  } UNION
  {
    SELECT DISTINCT ?attribute WHERE {
      ?class a kwg-ont:NOAAHazardEvent .
      ?class rdfs:label ?attribute .
    }
  } UNION
  {
    SELECT DISTINCT ?attribute WHERE {
      ?class a kwg-ont:StormTracklet .
      ?class geo:hasDefaultGeometry ?geometry .
      ?geometry geo:asWKT ?attribute .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?impactObservationCollection ?result
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
              rdfs:label "Wildfire" .
  ?impactObservationCollection a sosa:ObservationCollection ;
                              sosa:hasFeatureOfInterest ?hazardEvent .
  ?impactObservationCollection sosa:resultTime ?result .
}

PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>,
time: <http://www.w3.org/2006/time#>,
xsd: <http://www.w3.org/2001/XMLSchema#> ,
kwgr: <http://www.knowwheregraph.org/resource/>

SELECT ?damageDetails
WHERE {
    ?hazardEvent a kwg-ont:NOAAHazardEvent ;
        kwg-ont:hasSegment [a kwg-ont:EventSegment ; kwg-ont:endsAt ?fix ] .
    ?fix kwg-ont:hasGeometry ?geom1.
    ?hazardEvent geo:hasGeometry ?geom2.
    ?tornado a kwg-ont:NOAATornado;
          kwg-ont:spatialRelation ?administrativeRegion.
    ?administrativeRegion geo:hasGeometry ?geom3 .
        kwg-ont:spatialRelation ?s2Cell ;
        time:hasTemporalDuration [time:inXSDDateTime "????"^^xsd:date] .
    ?impactObs a sosa:Observation;
          sosa:observedProperty [a kwg-ont:ImpactObservableProperty];
          sosa:hasFeatureOfInterest ?hazardEvent ;
        sosa:phenomenonTime ?temporalEntity .
    BIND(CONCAT("Damage details by tornado-specific hazard ",?administrativeRegion) AS ?damageDetails)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?hazardDetails ?timeHappened
WHERE {
  {
    ?hazard a kwg-ont:DroughtZone .
    ?hazard geo:hasDefaultGeometry ?geometry .
    ?hazard kwg-ont:spatialRelation ?region .
    ?hazard kwg-ont:hasTemporalScope ?timeHappened .
    BIND(CONCAT("Drought Zone with geometry ", STR(?geometry), " in region ", STR(?region)) AS ?hazardDetails)
  } UNION {
    ?hazard a kwg-ont:Earthquake .
    ?hazard geo:hasDefaultGeometry ?geometry .
    ?hazard kwg-ont:sfWithin ?region .
    ?hazard kwg-ont:hasTemporalScope ?timeHappened .
    BIND(CONCAT("Earthquake with geometry ", STR(?geometry), " in region ", STR(?region)) AS ?hazardDetails)
  } UNION {
    ?hazard a kwg-ont:NOAAHazardEvent .
    ?hazard geo:hasDefaultGeometry ?geometry .
    ?hazard kwg-ont:spatialRelation ?region .
    ?hazard kwg-ont:hasTemporalScope ?timeHappened .
    BIND(CONCAT("NOAA Hazard Event with geometry ", STR(?geometry), " in region ", STR(?region)) AS ?hazardDetails)
  } UNION {
    ?hazard a kwg-ont:Fire .
    ?hazard geo:hasDefaultGeometry ?geometry .
    ?hazard kwg-ont:sfWithin ?region .
    ?hazard kwg-ont:hasTemporalScope ?timeHappened .
    BIND(CONCAT("Fire with geometry ", STR(?geometry), " in region ", STR(?region)) AS ?hazardDetails)
  } UNION {
    ?hazard a kwg-ont:SmokePlumeSnapshot .
    ?hazard geo:hasDefaultGeometry ?geometry .
    ?hazard kwg-ont:spatialRelation ?region .
    ?hazard kwg-ont:hasTemporalScope ?timeHappened .
    BIND(CONCAT("Smoke Plume Snapshot with geometry ", STR(?geometry), " in region ", STR(?region)) AS ?hazardDetails)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>

SELECT DISTINCT ?placeName WHERE {
  {
    ?place rdf:type kwg-ont:AdministrativeRegion .
    ?place geo:hasDefaultGeometry ?geometry .
    ?place kwg-ont:hasName ?placeName .
  } UNION {
    ?place rdf:type usgs:Division .
    ?place geo:hasDefaultGeometry ?geometry .
    ?place kwg-ont:hasName ?placeName .
  } UNION {
    ?place rdf:type usgs:BuiltUpArea .
    ?place geo:hasDefaultGeometry ?geometry .
    ?place kwg-ont:hasName ?placeName .
  } UNION {
    ?place rdf:type usgs:Terrain .
    ?place geo:hasDefaultGeometry ?geometry .
    ?place kwg-ont:hasName ?placeName .
  } UNION {
    ?place rdf:type usgs:SurfaceWater .
    ?place geo:hasDefaultGeometry ?geometry .
    ?place kwg-ont:hasName ?placeName .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?healthConcern ?attribute WHERE {
  {
    ?place a kwg-ont:AdministrativeRegion ;
           kwg-ont:hasGeometry ?geometry .

    ?healthConcern a kwg-ont:Hazard ;
                   geo:hasDefaultGeometry ?geometry .
  } UNION {
    ?place a kwg-ont:AdministrativeRegion ;
           kwg-ont:hasGeometry ?geometry .

    ?attribute a sosa:ObservableProperty ;
               sosa:isObservedBy ?observation .

    ?observation a sosa:Observation ;
                sosa:hasFeatureOfInterest ?place .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?demographicAttribute WHERE {
  VALUES ?demographicType { kwgr:censusObservableProperty.femalePopulation kwgr:censusObservableProperty.householdUnits kwgr:censusObservableProperty.malePopulation kwgr:censusObservableProperty.totalPopulation }
  ?demographicAttribute a ?demographicType .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
