    OPTIONAL { ?eventSegment sosa:observedProperty ?observableProperty .
               ?observableProperty rdfs:label ?attributeDetails . }

    FILTER (CONTAINS(str(?hazardAttribute), "Storm"))
  } UNION {
    ?stormSpecificHazard a kwg-ont:NOAAHazardEvent ;
                         kwg-ont:hasSegment ?eventSegment .

    OPTIONAL { ?eventSegment rdfs:comment ?attributeDetails . }
    OPTIONAL { ?eventSegment sosa:observedProperty ?observableProperty .
               ?observableProperty rdfs:label ?attributeDetails . }

    FILTER (CONTAINS(str(?hazardAttribute), "Storm"))
  } UNION {
    ?stormSpecificHazard a kwg-ont:NOAAHazardEvent ;
                         kwg-ont:hasSegment ?eventSegment .

    OPTIONAL { ?eventSegment rdfs:comment ?attributeDetails . }
    OPTIONAL { ?eventSegment sosa:observedProperty ?observableProperty .
               ?observableProperty rdfs:label ?attributeDetails . }

