PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardAttribute ?attributeDetails
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          rdfs:label ?hazardName .
  ?hazard rdfs:subClassOf* kwg-ont:Flood .
  OPTIONAL { ?hazard rdfs:comment ?attributeDetails . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?attribute
WHERE {
  ?place a kwg-ont:AdministrativeRegion ;
         kwg-ont:spatialRelation ?region .
  ?region a ?type ;
          rdfs:label ?attribute .
  FILTER(?type IN (kwg-ont:NWZone, kwg-ont:NielsenMarketZone, kwg-ont:USCensusMSA, kwg-ont:USClimateDivision))
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?impactFactorDetail
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  ?impactObservationCollection a kwg-ont:ImpactObservationCollection ;
                              sosa:hasFeatureOfInterest ?hazardEvent .
  ?impactObservation rdfs:type ?impactFactorDetail ;
                     sosa:observedProperty ?impactObservableProperty .
}

