           kwg-ont:spatialRelation ?geographicalPlace ;
           kwg-ont:hasTemporalScope ?temporalExtent .

  ?damageDetails a kwg-ont:ImpactObservation ;
                 sosa:observedProperty ?impactObservableProperty ;
                 sosa:hasFeatureOfInterest ?tornado .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?damageDetails WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          kwg-ont:hasSegment ?segment .
  ?segment a kwg-ont:EventSegment ;
           kwg-ont:affectedBy ?geographicalPlace .
  ?geographicalPlace a geo:Feature ;
                     geo:hasDefaultGeometry ?geometry .
  ?hazard kwg-ont:hasTemporalScope ?temporalExtent .
  ?damageDetails a kwg-ont:ImpactObservableProperty ;
                 sosa:observedProperty ?impactObservation .
  ?impactObservation a sosa:Observation ;
                     sosa:observedProperty ?damageDetails ;
                     sosa:hasFeatureOfInterest ?hazard .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/># Prefix for the knowledge graph schema
SELECT DISTINCT ?placeName WHERE {
  { ?place a geo:Feature .
    OPTIONAL {?place rdfs:label ?placeName.} }
  UNION
  { ?place a usgs:Terrain .
    OPTIONAL {?place rdfs:label ?placeName.} }
  UNION
  { ?place a usgs:BuiltUpArea .
    OPTIONAL {?place rdfs:label ?placeName.} }
  UNION
  { ?place a usgs:SurfaceWater .
    OPTIONAL {?place rdfs:label ?placeName.} }
  UNION
  { ?place a usgs:Division .
    OPTIONAL {?place rdfs:label ?placeName.} }
  FILTER(BOUND(?placeName))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sf: <http://www.opengis.net/ont/sf#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?placeName ?healthConcern
WHERE {
  {
    # HealthCareFacility and related properties
    ?place a kwg-ont:HealthCareFacility ;
            rdfs:label ?placeName .
    ?place kwg-ont:hospitalType|kwg-ont:helipadAvailability|kwg-ont:hospitalStatus|kwg-ont:noHospitalBeds|kwg-ont:traumaCareLevel ?healthConcern .
  } UNION {
    # PublicHealthDepartment and related properties
    ?place a kwg-ont:PublicHealthDepartment ;
            rdfs:label ?placeName .
    ?place kwg-ont:publicHealthDepartmentName|kwg-ont:pharmacyType ?healthConcern .
  } UNION {
    # Pharmacy and related properties
    ?place a kwg-ont:Pharmacy ;
            rdfs:label ?placeName .
    ?place kwg-ont:pharmacyName|kwg-ont:pharmacyType ?healthConcern .
  } UNION {
    # Hospital and related properties
    ?place a kwg-ont:Hospital ;
            rdfs:label ?placeName .
    ?place kwg-ont:hospitalStatus|kwg-ont:hospitalType|kwg-ont:noHospitalBeds|kwg-ont:helipadAvailability|kwg-ont:traumaCareLevel ?healthConcern .
  } UNION {
    # PublicHealthObservationCollection and related properties
    ?place a kwg-ont:PublicHealthObservationCollection ;
            rdfs:label ?placeName .
    ?place sosa:observedProperty ?observedProperty ;
            sosa:hasMember ?publicHealthObservation .
    ?observedProperty a kwgr:publicHealthObservableProperty.* ;
                      rdfs:label ?healthConcern .
  } UNION {
    # CensusACS5YearEstimatesObservationCollection and related properties
    ?place a kwg-ont:CensusACS5YearEstimatesObservationCollection ;
            rdfs:label ?placeName .
    ?place sosa:observedProperty ?observedProperty ;
            sosa:hasMember ?censusObservation .
    ?observedProperty a kwgr:censusObservableProperty.* ;
                      rdfs:label ?healthConcern .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?earthquakeHazard (COUNT(DISTINCT ?earthquakeHazard) AS ?count)
WHERE {
    ?earthquakeHazard a kwg-ont:Earthquake .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?attribute (COUNT(DISTINCT ?attribute) AS ?count)
WHERE {
  ?place a geo:Feature ;
         kwg-ont:spatialRelation ?region .
  ?region a kwg-ont:AdministrativeRegion .
  ?hazard a kwg-ont:NOAATornado ;
          sosa:hasFeatureOfInterest ?region ;
          kwg-ont:hasAttribute ?attribute .
}
GROUP BY ?attribute

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardAttribute ?attributeDetails WHERE {
  {
    ?stormSpecificHazard a kwg-ont:NOAAAstronomicalLowTide, kwg-ont:NOAAAvalanche, kwg-ont:NOAABlizzard,
                          kwg-ont:NOAACoastalFlood, kwg-ont:NOAAColdWindChill, kwg-ont:NOAADebrisFlow,
                          kwg-ont:NOAADenseFog, kwg-ont:NOAADenseSmoke, kwg-ont:NOAADrought, kwg-ont:NOAADustDevil,
                          kwg-ont:NOAADustStorm, kwg-ont:NOAAExcessiveHeat, kwg-ont:NOAAExtremeColdWindChill,
                          kwg-ont:NOAAFlashFlood, kwg-ont:NOAAFlood, kwg-ont:NOAAFreezingFog, kwg-ont:NOAAFrostFreeze,
                          kwg-ont:NOAAFunnelCloud, kwg-ont:NOAAHail, kwg-ont:NOAAHeat, kwg-ont:NOAAHeavyRain,
                          kwg-ont:NOAAHeavySnow, kwg-ont:NOAAHighSurf, kwg-ont:NOAAHighWind, kwg-ont:NOAAHurricane,
                          kwg-ont:NOAAIceStorm, kwg-ont:NOAALake-EffectSnow, kwg-ont:NOAALakeshoreFlood,
                          kwg-ont:NOAALightning, kwg-ont:NOAAMarineHail, kwg-ont:NOAAMarineHighWind,
                          kwg-ont:NOAAMarineHurricaneTyphoon, kwg-ont:NOAAMarineStrongWind,
                          kwg-ont:NOAAMarineThunderstormWind, kwg-ont:NOAAMarineTropicalDepression,
                          kwg-ont:NOAAMarineTropicalStorm, kwg-ont:NOAARipCurrent, kwg-ont:NOAASleet,
                          kwg-ont:NOAASneakerwave, kwg-ont:NOAAStormSurgeTide, kwg-ont:NOAAStrongWind,
                          kwg-ont:NOAAThunderstormWind, kwg-ont:NOAATornado, kwg-ont:NOAATropicalDepression,
                          kwg-ont:NOAATropicalStorm, kwg-ont:NOAAWaterspout, kwg-ont:NOAAWildfire, kwg-ont:NOAAWinterStorm,
                          kwg-ont:NOAAWinterWeather .

    ?hazardAttribute a sosa:ObservableProperty .
    ?stormSpecificHazard sosa:observedProperty ?hazardAttribute .
    OPTIONAL { ?hazardAttribute ?p ?attributeDetails . FILTER(isLiteral(?attributeDetails)) }
  } UNION {
    ?stormTrack a kwg-ont:StormTrack .
    ?geographicalPlace a geo:Feature, kwg-ont:Region .

    ?geographicalPlace ^kwg-ont:sfWithin ?stormTrack .
    ?stormTrack sosa:observedProperty ?hazardAttribute .
    ?hazardAttribute a sosa:ObservableProperty .
    OPTIONAL { ?hazardAttribute ?p ?attributeDetails . FILTER(isLiteral(?attributeDetails)) }
  } UNION {
    ?stormTracklet a kwg-ont:StormTracklet .
    ?geographicalPlace a geo:Feature, kwg-ont:Region .

    ?geographicalPlace ^kwg-ont:sfWithin ?stormTracklet .
    ?stormTracklet sosa:observedProperty ?hazardAttribute .
    ?hazardAttribute a sosa:ObservableProperty .
    OPTIONAL { ?hazardAttribute ?p ?attributeDetails . FILTER(isLiteral(?attributeDetails)) }
  } UNION {
    ?geographicalPlace a geo:Feature, kwg-ont:Region .

    ?stormSpecificHazard ^kwg-ont:spatialRelation ?geographicalPlace .
    ?stormSpecificHazard sosa:observedProperty ?hazardAttribute .
    ?hazardAttribute a sosa:ObservableProperty .
    OPTIONAL { ?hazardAttribute ?p ?attributeDetails . FILTER(isLiteral(?attributeDetails)) }
  } UNION {
    ?stormSpecificHazard ^kwg-ont:sfWithin ?geographicalPlace .
    ?geographicalPlace a geo:Feature, kwg-ont:Region .

    ?stormSpecificHazard sosa:observedProperty ?hazardAttribute .
    ?hazardAttribute a sosa:ObservableProperty .
    OPTIONAL { ?hazardAttribute ?p ?attributeDetails . FILTER(isLiteral(?attributeDetails)) }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardAttribute ?attributeValue WHERE {
  ?place a kwg-ont:AdministrativeRegion ;
         geo:hasDefaultGeometry ?geometry .
  ?hazard a kwg-ont:Hazard ;
          kwg-ont:sfWithin ?place ;
          ?attributeProperty ?hazardAttribute .
  ?hazardAttribute rdfs:label ?attributeValue .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?attribute WHERE {
  ?place a kwg-ont:AdministrativeRegion ;
         kwg-ont:hasAttribute ?attribute .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazardType ?hazardName ?propertyValue WHERE {
  {
    SELECT ?hazardType ?hazardName WHERE {
      ?hazard a kwg-ont:Earthquake .
      ?hazard rdfs:label ?hazardName .
    }
  } UNION {
    SELECT ?hazardType ?hazardName WHERE {
      ?hazard a sosa:ObservationCollection ;
              sosa:hasFeatureOfInterest ?earthquakeEvent .
      ?earthquakeEvent a kwg-ont:Earthquake ;
                      rdfs:label ?hazardName .
      BIND("Earthquake" as ?hazardType)
    }
  } UNION {
    SELECT ?propertyValue WHERE {
      ?observationCollection sosa:hasMember/sosa:observedProperty ?earthquakeObservableProperty .
      ?observationCollection a kwg-ont:EarthquakeObservationCollection ;
                            sosa:hasFeatureOfInterest ?earthquakeEvent .
      ?earthquakeEvent rdfs:label ?hazardName .
    }
  }

  OPTIONAL {
    ?propertyValue rdf:value ?value .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?damageDetail WHERE {
    ?hazard a kwg-ont:Hazard .
    ?damageDetail a kwg-ont:ImpactObservableProperty ;
                kwg-ont:affectedBy ?hazard .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardAttribute ?damageImpactDetails ?temporalData
WHERE {
  {
    SELECT DISTINCT ?hazardAttribute WHERE {
      ?hazard a kwg-ont:NOAAHurricane .
      ?hazard kwg-ont:sfWithin ?geographicalPlace .
      ?hazard sosa:hasFeatureOfInterest ?featureOfInterest .
      ?featureOfInterest rdfs:label ?hazardAttribute .
    }
  }
  {
    SELECT DISTINCT ?damageImpactDetails ?temporalData WHERE {
      ?impactObservation a kwg-ont:ImpactObservation ;
                          sosa:observedProperty ?impactObservableProperty ;
                          sosa:phenomenonTime ?phenomenonTime .
      ?impactObservableProperty rdfs:label ?damageImpactDetails .
      ?phenomenonTime time:inXSDDateTime ?temporalData .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?damageDetails WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          kwg-ont:hasSegment ?segment .
  ?segment kwg-ont:endsAt ?fix ;
           kwg-ont:startsFrom ?fix .
  ?fix geo:hasDefaultGeometry ?geometry .
  ?place kwg-ont:spatialRelation ?geometry .
  ?hazard a kwg-ont:NOAAHazardEvent ;
          kwg-ont:hasPart ?damageDetails .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?damageDetail
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
           kwg-ont:hasSegment ?segment .
  ?segment a kwg-ont:EventSegment ;
            kwg-ont:affectedBy ?geographicalPlace ;
            time:hasTime ?temporalExtent .
  ?damageDetail sosa:isFeatureOfInterestOf ?hazard .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardType ?hazardName ?temporalScope
WHERE {
  {
    SELECT ?hazardType WHERE { ?hazardType rdfs:subClassOf* kwg-ont:Hazard . }
  }
  OPTIONAL { ?hazardType kwg-ont:hasDisasterName ?hazardName . }
  OPTIONAL { ?hazardType kwg-ont:hasTemporalScope ?temporalScope . }
}
ORDER BY ?hazardType

