PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?place ?healthConcern
WHERE {
  {
    ?place rdfs:subClassOf* kwg-ont:AdministrativeRegion .
    ?healthConcern rdfs:subClassOf* kwg-ont:Hazard .
    ?place kwg-ont:spatialRelation ?healthConcern .
  } UNION {
    ?place rdfs:subClassOf* kwg-ont:AdministrativeRegion .
    ?healthConcern rdfs:subClassOf* kwg-ont:HealthCareFacility .
    ?place kwg-ont:sfWithin ?healthConcern .
  }
}

PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>

SELECT DISTINCT ?demographicAttribute ?value
WHERE {
  {
    SELECT ?demographicAttribute WHERE {
      ?demographicAttribute rdfs:subClassOf kwgr:censusObservableProperty.householdUnits .
    }
  } UNION {
    SELECT ?demographicAttribute WHERE {
      ?demographicAttribute rdfs:subClassOf kwgr:censusObservableProperty.totalPopulation .
    }
  } UNION {
    SELECT ?demographicAttribute WHERE {
      ?demographicAttribute rdfs:subClassOf kwgr:censusObservableProperty.malePopulation .
    }
  } UNION {
    SELECT ?demographicAttribute WHERE {
      ?demographicAttribute rdfs:subClassOf kwgr:censusObservableProperty.femalePopulation .
    }
  }

  ?place a geo:Feature ;
          kwg-ont:spatialRelation ?cell .

  ?observation sosa:hasFeatureOfInterest ?place ;
               sosa:observedProperty ?demographicAttribute ;
               sosa:hasSimpleResult ?value .

  FILTER(isLiteral(?value))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?attribute (COUNT(DISTINCT ?attribute) AS ?count)
WHERE {
  {
    SELECT DISTINCT ?attribute
    WHERE {
      {
        ?hazardType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
        ?hazardType ?p ?o .
        FILTER(isLiteral(?o))
        BIND(CONCAT(STR(?p), ":", STR(?o)) AS ?attribute)
      }
      UNION
      {
        ?hazardType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
        ?hazardType ?p ?o .
        FILTER(isURI(?o))
        BIND(CONCAT(STR(?p), ":", STR(?o)) AS ?attribute)
      }
    }
  }
}
GROUP BY ?attribute

