PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?damageDetail
WHERE {
  ?hazard a kwg-ont:Hazard ;
          kwg-ont:spatialRelation ?region .
  ?impactObservation a sosa:Observation ;
                     sosa:observedProperty ?impactObservableProperty ;
                     sosa:hasFeatureOfInterest ?hazard ;
                     sosa:phenomenonTime ?temporalEntity ;
                     sosa:hasSimpleResult ?damageDetail .
  ?impactObservableProperty rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardAttribute ?damageImpactDetail ?temporalData
WHERE {
  {
    SELECT ?hazardAttribute WHERE {
      ?hazardType rdfs:subClassOf* kwg-ont:NOAAHurricane .
      OPTIONAL { ?hazardType ?property ?value . }
      BIND(COALESCE(?property, ?value) AS ?hazardAttribute)
    }
  } UNION {
    SELECT ?damageImpactDetail WHERE {
      ?impactObservation a kwg-ont:ImpactObservation ;
                        sosa:observedProperty ?observableProperty .
      OPTIONAL { ?impactObservation ?property ?value . }
      BIND(COALESCE(?property, ?value) AS ?damageImpactDetail)
    }
  } UNION {
    SELECT ?temporalData WHERE {
      ?eventSegment a kwg-ont:EventSegment ;
                   kwg-ont:startsFrom ?fix1 ;
                   kwg-ont:endsAt ?fix2 .
      OPTIONAL { ?fix1 time:inXSDDateTime ?startTime . }
      OPTIONAL { ?fix2 time:inXSDDateTime ?endTime . }
      BIND(COALESCE(?startTime, ?endTime) AS ?temporalData)
    }
  }
}

PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?damageDetails
WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          rdfs:subClassOf* kwg-ont:StormSpecificHazard .
  ?hazard geo:hasGeometry ?geometry .
  ?hazard time:hasTemporalScope ?temporalExtent .
  ?impactObservation sosa:observedProperty kwgr:impactObservableProperty.damageCrop ;
                    sosa:phenomenonTime ?temporalExtent ;
                    sosa:hasFeatureOfInterest ?hazard ;
                    sosa:hasSimpleResult ?damageDetails .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?hazardEvent ?hazardType ?startDate ?endDate ?details
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }

  # Collect details about the hazard event
  BIND(
    COALESCE(
      CONCAT("Hazard Type: ", STR(?hazardType), " | Start Date: ", STR(?startDate), " | End Date: ", STR(?endDate)),
      CONCAT("Hazard Type: ", STR(?hazardType))
    ) AS ?details
  )
}
ORDER BY ?hazardEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?place ?healthAttribute WHERE {
  ?place rdf:type kwgl-ont:Place .
  {
    ?place kwgl-ont:percentDiabetic ?healthAttribute .
  } UNION {
    ?place kwgl-ont:percentObese ?healthAttribute .
  } UNION {
    ?place kwgl-ont:percentBelowPovertyLine ?healthAttribute .
  }
}
ORDER BY ?place

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?attribute
  (COUNT(DISTINCT ?attribute) AS ?count)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "tornado") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "tornado")
  )
}
GROUP BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

