PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardEvent ?impactFactor
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfFiresImpactingPlace ?impactFactor . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfFloodsImpactingPlace ?impactFactor . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?impactFactor . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?impactFactor . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?impactFactor . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?impactFactor . }
}
ORDER BY ?hazardEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?damageDetail
WHERE {
  ?place a kwgl-ont:Place .
  ?hazardEvent a kwgl-ont:HazardEvent ;
             kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageDetail . }

  FILTER (BOUND(?damageDetail))
}
ORDER BY ?damageDetail

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "hurricane")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?place ?hazardEvent ?damageDetail
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?hazardEvent a kwgl-ont:Hurricane ;
             kwgl-ont:hasImpacted ?place ;
             ?damageProperty ?damageValue .

  FILTER (CONTAINS(STR(?damageProperty), "dollarDamageOf") ||
          CONTAINS(STR(?damageProperty), "numberOf"))

  BIND(CONCAT("Damage by ", STR(?damageProperty)) AS ?damageDetail)

  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }

  FILTER (?startDate <= "2023-12-31"^^xsd:date && ?endDate >= "2023-01-01"^^xsd:date)
}
ORDER BY ?place ?hazardEvent

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?author WHERE {
    ?author a coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publication ?doi WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?department WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?university ?city WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?agent ?familyName ?firstName ?department WHERE {
  ?agent a coress-ont:Agent .
  OPTIONAL { ?agent coress-ont:hasFamilyName ?familyName . }
  OPTIONAL { ?agent coress-ont:hasFirstName ?firstName . }
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?city ?universityName ?collegeName WHERE {
  ?university coress-ont:atCity ?city ;
             coress-ont:hasCollege ?college .
  ?college rdfs:label ?collegeName .
  ?university rdfs:label ?universityName.
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?authorName ?advisorName ?publicationTitle ?fieldOfStudy WHERE {
  ?author a coress-ont:Author ;
          coress-ont:hasFirstName ?firstName ;
          coress-ont:hasFamilyName ?lastName ;
          coress-ont:advisedBy ?advisorName .
  ?author coress-ont:submits ?publication .
  ?publication coress-ont:hasTitle ?publicationTitle ;
               coress-ont:associatedFieldOfStudy ?fieldOfStudy .
  BIND(CONCAT(?firstName, " ", ?lastName) AS ?authorName)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName . }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

