SELECT DISTINCT ?featureName
WHERE {
  { ?feature rdf:type usgs:Feature .
    OPTIONAL { ?feature rdfs:label ?featureName . }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?healthConcern
WHERE {
  ?place rdf:type ?type .
  FILTER (CONTAINS(str(?type), "Hospital") || CONTAINS(str(?type), "Pharmacy") || CONTAINS(str(?type), "PublicHealthDepartment"))
  OPTIONAL { ?place kwg-ont:helipadAvailability ?healthConcern . }
  OPTIONAL { ?place kwg-ont:hospitalStatus ?healthConcern . }
  OPTIONAL { ?place kwg-ont:hospitalType ?healthConcern . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX terms: <http://purl.org/dc/terms/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX schema: <http://schema.org/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX wgs84_pos: <http://www.w3.org/2003/01/geo/wgs84_pos#>
PREFIX sf: <http://www.opengis.net/ont/sf#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?geographicPlace ?demographicAttribute
WHERE {
  {
    # Query for demographic attributes related to population
    ?geographicPlace rdf:type ?placeType .
    FILTER (CONTAINS(str(?placeType), "AdministrativeRegion") || CONTAINS(str(?placeType), "ZipCodeArea"))
    OPTIONAL { ?geographicPlace kwg-ont:sfWithin ?region . }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:censusObservableProperty.femalePopulation .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:censusObservableProperty.householdUnits .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:censusObservableProperty.malePopulation .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:censusObservableProperty.totalPopulation .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
  }
  UNION
  {
    # Query for demographic attributes related to health care facilities
    ?geographicPlace rdf:type ?placeType .
    FILTER (CONTAINS(str(?placeType), "AdministrativeRegion") || CONTAINS(str(?placeType), "ZipCodeArea"))
    OPTIONAL { ?geographicPlace kwg-ont:sfWithin ?region . }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:publicHealthObservableProperty.belowPovertyLevelPercent .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:publicHealthObservableProperty.diabetesAgeAdjusted20PlusPercent .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:publicHealthObservableProperty.fluVaccination .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:publicHealthObservableProperty.injuryAndDeaths .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:publicHealthObservableProperty.lowBirthWeight .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:publicHealthObservableProperty.mammographyScreening .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:publicHealthObservableProperty.mentalHealthProviders .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:publicHealthObservableProperty.obesityAgeAdjusted20PlusPercent .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:publicHealthObservableProperty.poorMentalHealthDays .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:publicHealthObservableProperty.uninsuredAdults .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
    OPTIONAL {
      ?demographicAttribute rdf:type kwgr:publicHealthObservableProperty.uninsuredChildren .
      ?observationCollection sosa:hasMember ?demographicAttribute .
      ?observationCollection sosa:hasFeatureOfInterest ?geographicPlace .
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX terms: <http://purl.org/dc/terms/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?hazardAttribute ?attributeDetails
WHERE {
  # Get all flood-specific hazard attributes (classes and properties)
  {
    SELECT DISTINCT ?hazardAttribute WHERE {
      # Find classes related to floods or water hazards
      { ?hazardAttribute rdfs:subClassOf* kwg-ont:Hazard .
        FILTER CONTAINS(str(?hazardAttribute), "Flood") }
      UNION
      # Find properties related to floods or water hazards
      { ?hazardAttribute a owl:ObjectProperty .
        VALUES (?relatedClass) {kwg-ont:NOAAFlood kwg-ont:NOAAStormSurgeTide kwg-ont:NOAACoastalFlood}
        FILTER CONTAINS(str(?hazardAttribute), "Flood") }
      UNION
      # Find properties related to floods or water hazards
      { ?hazardAttribute a owl:DatatypeProperty .
        VALUES (?relatedClass) {kwg-ont:NOAAFlood kwg-ont:NOAAStormSurgeTide kwg-ont:NOAACoastalFlood}
        FILTER CONTAINS(str(?hazardAttribute), "Flood") }
    }
  }

  # Get details for each hazard attribute
  OPTIONAL { ?hazardAttribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?hazardAttribute rdfs:comment ?attributeComment . }
  OPTIONAL { ?hazardAttribute skos:definition ?attributeDefinition . }
  BIND(COALESCE(?attributeLabel, COALESCE(?attributeComment, COALESCE(?attributeDefinition, "No details available"))) AS ?attributeDetails)
}
ORDER BY ?hazardAttribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX terms: <http://purl.org/dc/terms/>
PREFIX schema: <http://schema.org/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sf: <http://www.opengis.net/ont/sf#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?attribute
WHERE {
  {
    SELECT DISTINCT ?attribute WHERE {
      ?attribute rdf:type owl:NamedIndividual ;
                 rdfs:subClassOf* kwg-ont:Region .
    }
  } UNION {
    SELECT DISTINCT ?attribute WHERE {
      ?attribute rdf:type owl:NamedIndividual ;
                 rdfs:subClassOf* kwg-ont:HealthCareFacility .
    }
  } UNION {
    SELECT DISTINCT ?attribute WHERE {
