PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?fireType ?superType
WHERE {
  ?fireType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?fireType rdfs:subClassOf ?superType . }
}
ORDER BY ?fireType ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX terms: <http://purl.org/dc/terms/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?damageDetails
WHERE {
  ?hazard a kwg-ont:Hazard ;
          rdfs:label "Tornado" .
  ?hazardEvent a kwg-ont:NOAATornado ;
               kwg-ont:hasSegment ?segment .
  ?segment a kwg-ont:EventSegment ;
           kwg-ont:startsFrom ?startFix ;
           kwg-ont:endsAt ?endFix .
  ?startFix a kwg-ont:Fix ;
            geo:hasDefaultGeometry ?startGeo .
  ?endFix a kwg-ont:Fix ;
        geo:hasDefaultGeometry ?endGeo .
  ?geographicPlace a geo:Feature ;
                   geo:hasDefaultGeometry ?placeGeo .
  ?temporalExtent a time:TemporalEntity .
  ?hazardEvent kwg-ont:sfWithin ?geographicPlace ;
              kwg-ont:hasTemporalScope ?temporalExtent .
  ?impactObservationCollection a kwg-ont:ImpactObservationCollection ;
                              sosa:hasFeatureOfInterest ?hazardEvent ;
                              sosa:phenomenonTime ?temporalExtent .
  ?impactObservation a sosa:Observation ;
                     sosa:observedProperty ?impactObservableProperty ;
                     sosa:result ?damageDetails .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
