SELECT ?publication ?title ?dateOfSubmission
WHERE {
  ?publication a coress-ont:Publication .
  OPTIONAL { ?publication coress-ont:hasTitle ?title . }
  OPTIONAL { ?publication coress-ont:dateOfSubmission ?dateOfSubmission . }
}

