SELECT ?publication
WHERE {
  ?publication a coress-ont:Publication .
  ?author1 a coress-ont:Author ;
           coress-ont:submits ?publication ;
           coress-ont:performsRole [ rdf:type coress-ont:Agent ;
                                    coress-ont:worksInDepartment ?department1 ] .
  ?author2 a coress-ont:Author ;
           coress-ont:submits ?publication ;
           coress-ont:performsRole [ rdf:type coress-ont:Agent ;
                                    coress-ont:worksInDepartment ?department2 ] .
