WHERE {
  ?department a coress-ont:Department .
  ?department coress-ont:hasAgent ?agent .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?place ?name WHERE {
    ?place rdfs:subClassOf* geo:SpatialObject .
    OPTIONAL { ?place gnis:stateName ?name . }
    OPTIONAL { ?place usgs:elevation ?elevation . }
    OPTIONAL { ?place rdfs:label ?label . }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?attribute
WHERE {
  ?place rdf:type geo:Feature .
  ?place kwg-ont:spatialRelation ?administrativeRegion .
  ?observation sosa:hasFeatureOfInterest ?administrativeRegion ;
              sosa:observedProperty ?observableProperty ;
              sosa:hasSimpleResult ?attribute .
  VALUES ?observableType {
    kwgr:censusObservableProperty.householdUnits
    kwgr:censusObservableProperty.totalPopulation
  }
  FILTER(?observableProperty = ?observableType)
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardAttribute ?attributeDetails
WHERE {
  {
    ?hazardType a kwg-ont:NOAAHazardEvent .
    ?hazardAttribute rdfs:subClassOf sosa:ObservableProperty ;
                      rdfs:label ?attributeDetails .
    FILTER (STRSTARTS(STR(?hazardType), STR(kwg-ont:NOAATornado)))
  } UNION {
    ?hazardType a kwg-ont:NOAAHazardEvent .
    ?hazardAttribute rdfs:subClassOf sosa:ObservableProperty ;
                      rdfs:label ?attributeDetails .
    FILTER (STRSTARTS(STR(?hazardType), STR(kwg-ont:NOAAThunderstormWind)))
  } UNION {
    ?hazardType a kwg-ont:NOAAHazardEvent .
    ?hazardAttribute rdfs:subClassOf sosa:ObservableProperty ;
                      rdfs:label ?attributeDetails .
    FILTER (STRSTARTS(STR(?hazardType), STR(kwg-ont:NOAATropicalDepression)))
  } UNION {
    ?hazardType a kwg-ont:NOAAHazardEvent .
    ?hazardAttribute rdfs:subClassOf sosa:ObservableProperty ;
                      rdfs:label ?attributeDetails .
    FILTER (STRSTARTS(STR(?hazardType), STR(kwg-ont:NOAATropicalStorm)))
  } UNION {
    ?hazardType a kwg-ont:NOAAHazardEvent .
    ?hazardAttribute rdfs:subClassOf sosa:ObservableProperty ;
