    FILTER (STRSTARTS(STR(?hazardType), STR(kwg-ont:NOAAFlood)))
  } UNION {
    ?hazardType a kwg-ont:NOAAHazardEvent .
    ?hazardAttribute rdfs:subClassOf sosa:ObservableProperty ;
                      rdfs:label ?attributeDetails .
    FILTER (STRSTARTS(STR(?hazardType), STR(kwg-ont:NOAAFreezingFog)))
  } UNION {
    ?hazardType a kwg-ont:NOAAHazardEvent .
    ?hazardAttribute rdfs:subClassOf sosa:ObservableProperty ;
