  } UNION {
    ?hazardType a kwg-ont:NOAAHazardEvent .
    ?hazardAttribute rdfs:subClassOf sosa:ObservableProperty ;
                      rdfs:label ?attributeDetails .
    FILTER (STRSTARTS(STR(?hazardType), STR(kwg-ont:NOAAMarineTropicalStorm)))
  } UNION {
    ?hazardType a kwg-ont:NOAAHazardEvent .
    ?hazardAttribute rdfs:subClassOf sosa:ObservableProperty ;
                      rdfs:label ?attributeDetails .
    FILTER (STRSTARTS(STR(?hazardType), STR(kwg-ont:NOAASneakerwave)))
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazardEvent ?observationProperty ?result
WHERE {
  ?hazardEvent rdfs:subClassOf kwg-ont:Hazard .
  ?impactObservation sosa:hasFeatureOfInterest ?hazardEvent ;
                    sosa:observedProperty ?observationProperty ;
                    sosa:hasSimpleResult ?result .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT ?damageDetails WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent .
  ?impactObservation a sosa:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazard ;
                     sosa:observedProperty ?impactObservableProperty .
  ?impactObservableProperty rdfs:subClassOf* ?damageType .
  ?damageDetails a ?damageType .
}

PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?damageDetail
WHERE {
  ?hazard a kwg-ont:NOAATornado ;
          geo:hasGeometry ?geometry ;
          time:inXSDDateTime ?startTime ;
          time:inXSDDateTime ?endTime ;
          sosa:observedProperty ?property .
  ?impactObservation a sosa:ImpactObservation ;
                     sosa:hasFeatureOfInterest ?hazard ;
                     sosa:phenomenonTime ?time ;
                     sosa:observedProperty ?damageProperty ;
                     sosa:hasSimpleResult ?damageDetail .
  ?property rdfs:subClassOf kwgr:magnitudeObservableProperty.fujitaScale .
  FILTER(?startTime <= ?time && ?time <= ?endTime) .
}

PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?damageDetails ?geographicalPlace WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
              kwg-ont:hasTemporalScope ?temporalExtent ;
              geo:hasGeometry ?geometry ;
              geo:spatialRelation ?geographicalPlace .

  ?impactObservation sosa:observedProperty kwgr:impactObservableProperty.damageCrop .
  ?impactObservation sosa:phenomenonTime ?temporalExtent .
  ?impactObservation sosa:hasSimpleResult ?damageDetails .

  ?geographicalPlace geo:hasGeometry ?geometry .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiString
WHERE {
  ?publication coresr-ont:hasIdentifier ?doi .
  ?doi coresr-ont:doiAsString ?doiString.
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?title ?submissionDate WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:hasTitle ?title .
  OPTIONAL {?publication coresr-ont:dateOfSubmission ?submissionDate.}
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?typeString
WHERE {
  ?publication coresr-ont:hasPublicationType ?publicationType .
  ?publicationType coresr-ont:typeAsString ?typeString .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?title ?fieldOfStudy WHERE {
  ?publication coresr-ont:hasTitle ?title .
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy.
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?city ?university ?college WHERE {
  ?university coresr-ont:locatedAt ?location .
  ?location coresr-ont:inCity ?city .
  ?university coresr-ont:hasPart ?college .
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publicationType (AVG(?timeBetween) AS ?avgTime)
WHERE {
  ?publication a coresr-ont:Publication ;
              coresr-ont:hasPublicationType ?publicationType ;
              coresr-ont:dateOfSubmission ?submissionDate ;
              coresr-ont:dateOfPublication ?publicationDate .
  BIND(xsd:integer((?publicationDate - ?submissionDate)) AS ?timeBetween)
}
GROUP BY ?publicationType
ORDER BY DESC(?avgTime)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisorName ?publicationTitle ?fieldName WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
  ?author coresr-ont:submits ?publication .
  OPTIONAL {?publication coresr-ont:hasTitle ?publicationTitle .}
  OPTIONAL {?advisor coresr-ont:nameAsString ?advisorName .}
  OPTIONAL {
    ?publication coresr-ont:associatedFieldOfStudy ?field .
    OPTIONAL {?field coresr-ont:typeAsString ?fieldName . }
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?department a coresr-ont:Department ;
              coresr-ont:hasAssociatedAgent ?agent .
  FILTER NOT EXISTS { ?agent coresr-ont:hasContactInformation/_coresr-ont:nameAsString ?familyName . }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?hazardType ?startDate ?endDate ?details
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasHazardType ?hazardType .
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL {
    {
      ?hazard kwgl-ont:dollarDamageOfFiresImpactingPlace ?damage .
      BIND(CONCAT("Fire damage: ", ?damage, " dollars") AS ?details)
    } UNION {
      ?hazard kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damage .
      BIND(CONCAT("Flood damage: ", ?damage, " dollars") AS ?details)
    } UNION {
      ?hazard kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damage .
      BIND(CONCAT("Hurricane damage: ", ?damage, " dollars") AS ?details)
    } UNION {
      ?hazard kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?damage .
      BIND(CONCAT("Landslide damage: ", ?damage, " dollars") AS ?details)
    } UNION {
      ?hazard kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?damage .
      BIND(CONCAT("Storm surge damage: ", ?damage, " dollars") AS ?details)
    } UNION {
      ?hazard kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damage .
      BIND(CONCAT("Tornado damage: ", ?damage, " dollars") AS ?details)
    }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
