PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?place ?population ?householdUnits WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?householdUnits . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?attributeName ?attributeValue WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasImpacted|kwgl-ont:impactedBy ?hazardEvent .
  ?hazardEvent a kwgl-ont:HazardEvent .
  FILTER (kwgl-ont:Flood = ?hazardEvent) .
  {
    SELECT ?attributeName WHERE {
      ?place ?property ?value .
      FILTER (isLiteral(?value)) .
      BIND(REPLACE(str(?property), "http://www.kwg-lite.org/ontology/", "") AS ?attributeName)
    }
  } UNION {
    SELECT ?attributeName WHERE {
      ?hazardEvent ?property ?value .
      FILTER (isLiteral(?value)) .
      BIND(REPLACE(str(?property), "http://www.kwg-lite.org/ontology/", "") AS ?attributeName)
    }
  }
  {
    SELECT ?attributeValue WHERE {
      ?place ?property ?value .
      FILTER (isLiteral(?value)) .
      BIND(?value AS ?attributeValue)
    }
  } UNION {
    SELECT ?attributeValue WHERE {
      ?hazardEvent ?property ?value .
      FILTER (isLiteral(?value)) .
      BIND(?value AS ?attributeValue)
    }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?dollarDamageOfFiresImpactingPlace ?dollarDamageOfFloodsImpactingPlace
                      ?dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace
                      ?dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamageOfFiresImpactingPlace . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfStormSurgesImpactingPlace . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardAttribute ?damageImpactDetail ?temporalData WHERE {
  ?place a kwgl-ont:Place .
  ?hurricane a kwgl-ont:Hurricane ;
            kwgl-ont:hasImpacted ?place .

  # Hurricane-specific hazard attributes
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hazardAttribute . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hazardAttribute . }

  # Damage impact details and temporal data
  OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?temporalData . }
  OPTIONAL { ?hurricane kwgl-ont:hasEndDate ?temporalData . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?damageImpactDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?damageImpactDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?damageImpactDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?damageImpactDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?damageImpactDetail . }

  FILTER (bound(?hazardAttribute) || bound(?damageImpactDetail))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?damageDetail WHERE {
  ?tornado a kwgl-ont:Tornado ;
           kwgl-ont:hasImpacted ?place ;
           kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageDetail .
  ?place a kwgl-ont:Place .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?place ?damageDetails
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  ?hazardEvent kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:sfIntersects ?place .

  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfFiresImpactingPlace ?damageDetails . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damageDetails . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageDetails . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?damageDetails . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?damageDetails . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageDetails . }

  FILTER ( ?damageDetails > 0 )
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazard, ?details, ?whenHappened
WHERE {
  { # Select hazards with available details and temporal scope information
    SELECT ?hazard (GROUP_CONCAT(DISTINCT ?detailProperty; SEPARATOR=", ") AS ?details) ?whenHappened
    WHERE {
      # Filter for hazards that have available details and temporal scope information
      VALUES ?hazardType { kwg-ont:Earthquake, kwg-ont:DroughtZone, kwg-ont:NOAAHurricane }

      ?hazard rdf:type ?hazardType ;
               kwg-ont:hasTemporalScope ?timeEntity ;
               [ a ?propertyClass ;
                 rdfs:label ?detailProperty
               ] .
      BIND(DATETIME(?timeEntity) AS ?whenHappened)
    }
  }
} ORDER BY ?hazard ?details

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX core: <http://purl.org/vocab/frbr/core/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>

SELECT DISTINCT ?featureType ?officialName WHERE {
  {
    ?feature rdf:type ?featureType ;
              usgs:officialName ?officialName .
  }
}
ORDER BY ?officialName

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX wgs84_pos: <http://www.w3.org/2003/01/geo/wgs84_pos#><http://www.opengis.net/ont/geosparql#>
SELECT DISTINCT ?property WHERE {
  { SELECT DISTINCT ?property WHERE {
      VALUES (?class) { kwg-ont:Hospital }
      VALUES (?property) {kwg-ont:sfWithin , kwg-ont:spatialRelation, geo:hasGeometry}
    }
  } UNION
  {
      VALUES (?class) { kwg-ont:NielsenMarketZone }
      VALUES (?property) {kwg-ont:sfWithin , kwg-ont:spatialRelation, geo:hasGeometry}
  }
  UNION {
    SELECT DISTINCT ?property WHERE {
      VALUES (?class) { kwg-ont:USCensusMSA }
      VALUES (?property) {kwg-ont:typeOfLSAD}
    }
  }
  UNION {
      VALUES (?class) { kwg-ont:AdministrativeRegion_3 }
      VALUES (?property) {geo:hasGeometry}
  }
   UNION
  {
    SELECT DISTINCT ?property WHERE {
      VALUES (?class) { kwg-ont:ZipCodeArea }
      VALUES (?property) {kwg-ont:spatialRelation, geo:hasGeometry}
    }
  }
   UNION {
     SELECT DISTINCT ?property WHERE {
        VALUES(?class) {kwg-ont:Region , kwg-ont:NWZone}
        VALUES (?property) {geo:hasDefaultGeometry , geo:hasGeometry}
     }
   }
   UNION
  {
      VALUES (?class) {kwg-ont:TraumaCenter}
      VALUES (?property) {kwg-ont:traumaCareLevel, geo:hasGeometry, kwg-ont:sfWithin}
  }

UNION
    SELECT DISTINCT ?property WHERE {
        VALUES (?class) {kwg-ont:Pharmacy }
          VALUES (?property) {geo:hasDefaultGeometry , geo:hasGeometry}
  }
   UNION {
     SELECT DISTINCT ?property WHERE {
        VALUES(?class) {kwg-ont:HospitalType, kwg-ont:HelipadAvailability, kwg-ont:HospitalStatus}
       VALUES (?property) {}
    }

UNION
{
    SELECT DISTINCT ?property WHERE {
        VALUES (?class) {kwg-ont:Region , kwg-ont:NWZone}
        VALUES (?property) {geo:hasDefaultGeometry , geo:hasGeometry}

  }
}
} LIMIT 100

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?name
WHERE {
  ?hazard a kwg-ont:Hazard ;
          geo:hasDefaultGeometry|geo:hasGeometry ?geom .
}

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX schema: <http://schema.org/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX terms: <http://purl.org/dc/terms/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX wgs84_pos: <http://www.w3.org/2003/01/geo/wgs84_pos#>

SELECT DISTINCT ?floodAttribute ?attributeDetails
WHERE {
  # Select hazard attributes that are specific to floods or related flood hazards
  ?floodHazardType rdf:type owl:Class ;
                   rdfs:subClassOf* kwg-ont:Flood .

  # Get the properties of each flood hazard type
  OPTIONAL { ?floodAttribute a owl:DatatypeProperty, owl:ObjectProperty ;
            rdfs:domain ?floodHazardType .
          }

  # Get labels and comments for each property to serve as details
  OPTIONAL { ?floodAttribute rdfs:label ?attributeLabel .
           }
  OPTIONAL { ?floodAttribute skos:definition ?attributeDescription .
           }

  # Combine results with the flood hazard type information
  BIND (CONCAT(?floodHazardType, " - ", STR(?floodAttribute)) AS ?floodAttributeName)
  UNION {
    BIND (IF(BOUND(?attributeLabel), ?attributeLabel, "No label provided") AS ?attributeDetails)
  }
}

