      OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?attributeValue . BIND("Average Cooling Degree Days Per Month" AS ?attributeName) }
      UNION
      OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?attributeValue . BIND("Average Heating Degree Days Per Month" AS ?attributeName) }
      UNION
      OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?attributeValue . BIND("Average Monthly Temperature In Celsius" AS ?attributeName) }
      UNION
      OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?attributeValue . BIND("Maximum Monthly Temperature In Celsius" AS ?attributeName) }
      UNION
      OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?attributeValue . BIND("Minimum Monthly Temperature In Celsius" AS ?attributeName) }
      UNION
      OPTIONAL { ?place kwgl-ont:hasPopulation ?attributeValue . BIND("Has Population" AS ?attributeName) }
      UNION
      OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?attributeValue . BIND("Percent Below Poverty Line" AS ?attributeName) }
      UNION
      OPTIONAL { ?place kwgl-ont:percentDiabetic ?attributeValue . BIND("Percent Diabetic" AS ?attributeName) }
      UNION
      OPTIONAL { ?place kwgl-ont:percentObese ?attributeValue . BIND("Percent Obese" AS ?attributeName) }
    }
  }
}

