PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX terms: <http://purl.org/dc/terms/>

SELECT DISTINCT ?hazardType ?property ?value
WHERE {
  {
    SELECT ?place WHERE { ?place rdf:type kwgl-ont:Place . }
  }
  OPTIONAL { ?place kwgl-ont:hasImpacted ?event . }
  OPTIONAL { ?event kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL {
    ?place ?property ?value .
    FILTER (
      ?property IN (kwgl-ont:averageCoolingDegreeDaysPerMonth,
                     kwgl-ont:averageHeatingDegreeDaysPerMonth,
                     kwgl-ont:averageMonthlyTemperatureInCelsius,
                     kwgl-ont:maximumMonthlyTemperatureInCelsius,
                     kwgl-ont:minimumMonthlyTemperatureInCelsius)
    )
  }
}

