  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2022 ?attributeValue . BIND("dollar damage of floods impacting place (2022)" AS ?attributeName) }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?attributeValue . BIND("number of floods impacting place" AS ?attributeName) }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2018 ?attributeValue . BIND("number of floods impacting place (2018)" AS ?attributeName) }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2019 ?attributeValue . BIND("number of floods impacting place (2019)" AS ?attributeName) }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2020 ?attributeValue . BIND("number of floods impacting place (2020)" AS ?attributeName) }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2021 ?attributeValue . BIND("number of floods impacting place (2021)" AS ?attributeName) }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2022 ?attributeValue . BIND("number of floods impacting place (2022)" AS ?attributeName) }
}

