PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?hazardTypeName ?startDate ?endDate
WHERE {
  ?hazardEvent rdf:type kwglr:earthquake .
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazardType rdfs:label ?hazardTypeName . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?hasName ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hasName . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?placeName ?hazardType ?damageToCropsInDollars ?damageToInfrastructureInDollars
       ?dollarDamageOfFiresImpactingPlace ?dollarDamageOfFloodsImpactingPlace
       ?dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace
       ?dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace
       ?averageMonthlyTemperatureInCelsius ?maximumMonthlyTemperatureInCelsius
       ?minimumMonthlyTemperatureInCelsius ?numberOfDeaths ?hasStartDate ?hasEndDate
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .
  OPTIONAL { ?place kwgl-ont:impactedBy ?hazardEvent . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType kwglr:hurricane . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamageOfFiresImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfStormSurgesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?averageMonthlyTemperatureInCelsius . }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?maximumMonthlyTemperatureInCelsius . }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?minimumMonthlyTemperatureInCelsius . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?hasStartDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?hasEndDate . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?placeName ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Tornado ;
               kwgl-ont:hasHazardType kwglr:tornado ;
               kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?place ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasHazardType kwglr:wildfire .
  ?place a kwgl-ont:Place ;
         kwgl-ont:impactedBy ?hazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardEvent ?hazardTypeLabel ?startDate ?endDate
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazardType rdfs:label ?hazardTypeLabel . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
}
ORDER BY ?hazardEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
