SELECT DISTINCT ?place ?name
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?property ?label WHERE {
  {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "temperature") ||
            CONTAINS(LCASE(STR(?label)), "temperature"))
  } UNION {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "degree") ||
            CONTAINS(LCASE(STR(?label)), "degree"))
  } UNION {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "cooling") ||
            CONTAINS(LCASE(STR(?label)), "cooling"))
  } UNION {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "heating") ||
            CONTAINS(LCASE(STR(?label)), "heating"))
  } UNION {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "dollar") ||
            CONTAINS(LCASE(STR(?label)), "dollar"))
  } UNION {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "damage") ||
            CONTAINS(LCASE(STR(?label)), "damage"))
  } UNION {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "population") ||
            CONTAINS(LCASE(STR(?label)), "population"))
  } UNION {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "household") ||
            CONTAINS(LCASE(STR(?label)), "household"))
  } UNION {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "obese") ||
            CONTAINS(LCASE(STR(?label)), "obese"))
  } UNION {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "diabetic") ||
            CONTAINS(LCASE(STR(?label)), "diabetic"))
  } UNION {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "poverty") ||
            CONTAINS(LCASE(STR(?label)), "poverty"))
  } UNION {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "death") ||
            CONTAINS(LCASE(STR(?label)), "death"))
  } UNION {
    ?property rdf:type owl:DatatypeProperty .
    OPTIONAL { ?property rdfs:label ?label . }
    FILTER (CONTAINS(LCASE(STR(?property)), "area") ||
            CONTAINS(LCASE(STR(?label)), "area"))
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?attribute (COUNT(DISTINCT ?attribute) AS ?count)
WHERE {
  {
    ?attribute rdf:type owl:DatatypeProperty .
    FILTER CONTAINS(LCASE(STR(?attribute)), "tornado")
  }
}
GROUP BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?attribute ?attributeLabel ?range ?parentAttribute ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "storm")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?attribute ?attributeLabel ?range ?parentAttribute ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }
  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazardType ?hazardTypeLabel ?hazardEvent ?hazardEventName ?startDate ?endDate
WHERE {
  ?hazardType rdf:type owl:NamedIndividual ;
              rdfs:label ?hazardTypeLabel .
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType ?hazardType ;
               kwgl-ont:hasName ?hazardEventName ;
               OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
               OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  FILTER (CONTAINS(LCASE(STR(?hazardTypeLabel)), "earthquake"))
}
ORDER BY ?hazardType

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "hurricane")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?placeName ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths ?affectedAreaInAcres
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Tornado ;
               kwgl-ont:hasHazardType <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/tornado> ;
               kwgl-ont:hasImpacted ?place .

  ?place rdf:type kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName .
         OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
         OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
         OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
         OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }

  # Filter for a specific temporal extent (example: year 2021)
  OPTIONAL {
    ?hazardEvent kwgl-ont:hasStartDate ?startDate .
    FILTER (YEAR(?startDate) = 2021)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?placeName ?hazardEventName ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths ?hasStartDate ?hasEndDate
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .

  ?hazardEvent rdf:type kwgl-ont:HazardEvent ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasName ?hazardEventName ;
               kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars ;
               kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars ;
               kwgl-ont:numberOfDeaths ?numberOfDeaths ;
               kwgl-ont:hasStartDate ?hasStartDate ;
               kwgl-ont:hasEndDate ?hasEndDate .

  FILTER (CONTAINS(LCASE(STR(?hazardEventName)), "storm") || CONTAINS(LCASE(STR(?hazardEventName)), "hurricane"))
}
ORDER BY ?placeName

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?hazardDetails WHERE {
    # Get the hazard details
    ?hazard rdf:type kwg-ont:Hazard .
    OPTIONAL { ?hazard rdfs:label ?hazardName . }
    BIND(GROUP_CONCAT(DISTINCT CONCAT(" - ", ?hazardName) ; separator: " ") AS ?hazardDetails) WHERE {
        FILTER EXISTS { ?hazard a kwg-ont:Hazard }
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?place ?name WHERE {
  ?place rdf:type usgs:Terrain ;
    kwg-ont:sfWithin ?admRegion .
  ?admRegion rdfs:label ?name .
}

