    FILTER(isLiteral(?geoFeature))
  }
  UNION
  {
    ?geoFeature a usgs:Tower .
    FILTER(isLiteral(?geoFeature))
  }
  UNION
  {
    ?geoFeature a usgs:Trail .
    FILTER(isLiteral(?geoFeature))
  }
  UNION
  {
    ?geoFeature a usgs:Tunnel .
    FILTER(isLiteral(?geoFeature))
  }
  UNION
  {
    ?geoFeature a usgs:Unknown .
    FILTER(isLiteral(?geoFeature))
  }
  UNION
  {
    ?geoFeature a usgs:Valley .
    FILTER(isLiteral(?geoFeature))
  }
  UNION
  {
    ?geoFeature a usgs:Waterfall .
    FILTER(isLiteral(?geoFeature))
  }
  UNION
  {
    ?geoFeature a usgs:Well .
    FILTER(isLiteral(?geoFeature))
  }
  UNION
  {
    ?geoFeature a usgs:Woodland .
    FILTER(isLiteral(?geoFeature))
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
