PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX : <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT ?subject ?predicate ?object
WHERE {
  { ?subject rdf:type kwg-ont:Hospital . }
  UNION { ?subject a kwg-ont:Pharmacy . }
  UNION { ?subject a kwg-ont:PublicHealthDepartment . }

  ?subject ?predicate ?object .
}
ORDER BY ?subject

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardType (COUNT(?hazard) as ?count)
WHERE {
  ?hazard a kwg-ont:Hazard .
  OPTIONAL { ?hazard a ?hazardType . }
}
GROUP BY ?hazardType

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?attributeName (COUNT(?attributeName) AS ?count)
WHERE {
  {
    ?hazard rdf:type kwg-ont:Hazard .
    ?geogPlace rdf:type geo:Feature .
    ?tornado rdf:type kwg-ont:NOAATornado .
    ?eventSegment rdf:type kwg-ont:EventSegment .
    ?attributeName rdfs:label ?attributeLabel .

    # Query for attribute names of tornado-specific hazard related to all geographical places
    {
      ?hazard a kwg-ont:Tornado ;
              owl:sameAs ?tornado .
      # Ensure the tornado is spatially related to the geogPlace
      ?tornado geo:sfWithin ?geogPlace .

      # Include attributes from both Tornado and Geographical Place classes
      ?hazard rdfs:label|rdf:type ?attributeName .
    } UNION {
      ?geogPlace rdfs:label|rdf:type ?attributeName .
    }
  }
}
GROUP BY ?attributeName

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geocode: <http://ld.iospress.nl/rdf/geocode/>
PREFIX terms: <http://purl.org/dc/terms/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
SELECT DISTINCT ?hazardAttribute ?hazardAttributeLabel WHERE {
  # Query storm-specific hazard attributes related to all geographical places
  VALUES (?attributeType) { kwg-ont:NOAAHazard }

  # Get all hazard attribute properties
  BIND(?property AS ?hazardAttribute)
  OPTIONAL {
    ?attributeType rdfs:subClassOf+ ?superclass .
    ?superclass rdfs:subPropertyOf* ?property .
    ?attributeType rdfs:label ?attributeLabel .

    # Get the label for each property
    BIND(CONCAT(STR(?attributeType), " | ", STR(?attributeLabel)) AS ?hazardAttributeLabel)
  }

  OPTIONAL {
    FILTER NOT EXISTS { ?property rdf:type owl:Axiom }
    FILTER NOT EXISTS { ?property a owl:AnnotationProperty }
    BIND(CONCAT("Property Label: ", STR(?property), " | ", " Property URI: ", STR(?attributeType)) AS ?hazardAttributeLabel)
  }

}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
