}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
SELECT ?damage_details WHERE {
    ?damageDetails rdf:type kwg-ont:DamageDetails .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?damageDetails WHERE {
  ?tornadoDamageDetails a kwg-ont:ImpactObservation ;
                        kwg-ont:target [a kwg-ont:NOAATornado ;
                                        geo:hasGeometry ?geometry] ;
                        sosa:observedProperty [rdfs:subClassOf kwg-ont:damageProperty] .

  OPTIONAL {?tornadoDamageDetails sosa:hasResult/kwg-ont:value ?damageDetails} .
}

