SELECT DISTINCT ?place ?population ?householdUnits
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?householdUnits . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?attribute (COUNT(DISTINCT ?attribute) AS ?count)
WHERE {
  {
    SELECT DISTINCT ?attribute
    WHERE {
      ?place a kwgl-ont:Place .
      ?place ?attribute ?value .
      FILTER(CONTAINS(STR(?attribute), "Tornado"))
    }
  }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardAttribute ?attributeValue WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:impactedBy ?hazardEvent .
  ?hazardEvent a kwgl-ont:HazardEvent .
  ?hazardEvent kwgl-ont:hasHazardType kwglr:flood .

  # Select all attributes related to the place
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?attributeValue . BIND("averageCoolingDegreeDaysPerMonth" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?attributeValue . BIND("averageHeatingDegreeDaysPerMonth" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?attributeValue . BIND("averageMonthlyTemperatureInCelsius" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:damageToCropsInDollars ?attributeValue . BIND("damageToCropsInDollars" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:damageToInfrastructureInDollars ?attributeValue . BIND("damageToInfrastructureInDollars" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?attributeValue . BIND("dollarDamageOfFiresImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?attributeValue . BIND("dollarDamageOfFloodsImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?attributeValue . BIND("dollarDamageOfHurricanesImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?attributeValue . BIND("dollarDamageOfLandslidesImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?attributeValue . BIND("dollarDamageOfStormSurgesImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?attributeValue . BIND("dollarDamageOfTornadoesImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:hasName ?attributeValue . BIND("hasName" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?attributeValue . BIND("hasNumberOfHouseHolds" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?attributeValue . BIND("hasPopulation" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?attributeValue . BIND("maximumMonthlyTemperatureInCelsius" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?attributeValue . BIND("minimumMonthlyTemperatureInCelsius" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:numberOfEarthquakesImpactingPlace ?attributeValue . BIND("numberOfEarthquakesImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:numberOfFiresImpactingPlace ?attributeValue . BIND("numberOfFiresImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?attributeValue . BIND("numberOfFloodsImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?attributeValue . BIND("numberOfHurricanesImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:numberOfLandslidesImpactingPlace ?attributeValue . BIND("numberOfLandslidesImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?attributeValue . BIND("numberOfStormSurgesImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?attributeValue . BIND("numberOfTornadoesImpactingPlace" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?attributeValue . BIND("percentBelowPovertyLine" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?attributeValue . BIND("percentDiabetic" AS ?hazardAttribute) }
  OPTIONAL { ?place kwgl-ont:percentObese ?attributeValue . BIND("percentObese" AS ?hazardAttribute) }

  # Select all attributes related to the hazard event
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?attributeValue . BIND("affectedAreaInAcres" AS ?hazardAttribute) }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?attributeValue . BIND("damageToCropsInDollars" AS ?hazardAttribute) }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?attributeValue . BIND("damageToInfrastructureInDollars" AS ?hazardAttribute) }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?attributeValue . BIND("hasEndDate" AS ?hazardAttribute) }
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?attributeValue . BIND("hasName" AS ?hazardAttribute) }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?attributeValue . BIND("hasStartDate" AS ?hazardAttribute) }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?attributeValue . BIND("numberOfDeaths" AS ?hazardAttribute) }

  FILTER(BOUND(?hazardAttribute))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?earthquake ?hazardType ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?hasEndDate ?hasName ?hasStartDate ?numberOfDeaths
WHERE {
  ?earthquake rdf:type kwgl-ont:Earthquake .
  ?earthquake kwgl-ont:hasHazardType ?hazardType .
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?hasEndDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasName ?hasName . }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?hasStartDate . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardAttribute ?damageImpactDetail ?temporalData WHERE {
  ?hurricane a kwgl-ont:Hurricane ;
             kwgl-ont:hasHazardType kwglr:hurricane ;
             kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hurricane ?hazardAttribute ?value . FILTER(isLiteral(?value)) }

  OPTIONAL {
    ?hurricane kwgl-ont:damageToCropsInDollars ?cropsDamage .
    BIND(CONCAT("Damage to crops: ", STR(?cropsDamage), " dollars") AS ?damageImpactDetail)
  }

  OPTIONAL {
    ?hurricane kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage .
    BIND(CONCAT("Damage to infrastructure: ", STR(?infrastructureDamage), " dollars") AS ?damageImpactDetail)
  }

  OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?startDate . BIND(?startDate AS ?temporalData) }
  OPTIONAL { ?hurricane kwgl-ont:hasEndDate ?endDate . BIND(?endDate AS ?temporalData) }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazardEvent ?eventName ?hazardType ?startDate ?endDate ?place ?placeName ?details
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent ;
               kwgl-ont:hasStartDate ?startDate ;
               kwgl-ont:hasEndDate ?endDate ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:hasName ?eventName .

  ?hazardType rdf:type owl:NamedIndividual ,
                      kwgl-ont:HazardType ;
             rdfs:label ?hazardLabel .
  ?hazardEvent kwgl-ont:hasHazardType ?hazardType .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }

  OPTIONAL {
    UNION {
      { ?hazardEvent kwgl-ont:numberOfDeaths ?deathCount .
        BIND(CONCAT("Number of deaths: ", STR(?deathCount)) AS ?details) }
      { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage .
        BIND(CONCAT("Crop damage: $", STR(?cropDamage)) AS ?details) }
      { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage .
        BIND(CONCAT("Infrastructure damage: $", STR(?infrastructureDamage)) AS ?details) }
    }
  }
}
ORDER BY ?startDate

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?placeName
WHERE {
  ?place rdf:type kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?attribute ?attributeLabel ?range ?parentAttribute ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }
  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "storm")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX terms: <http://purl.org/dc/terms/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
    ?attribute
    (GROUP_CONCAT(DISTINCT ?label; separator=", ") AS ?labels)
WHERE {
  {
    SELECT ?attribute WHERE {
      ?attribute rdf:type owl:DatatypeProperty .
      FILTER CONTAINS(STR(?attribute), "flood")
    }
  }

  OPTIONAL { ?attribute rdfs:label ?label . }

}
GROUP BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?property
WHERE {
  {
    SELECT ?property
    WHERE {
      ?property rdf:type owl:DatatypeProperty ;
                rdfs:domain kwgl-ont:Place .
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?hazardType (GROUP_CONCAT(DISTINCT ?detailProperty; separator=", ") AS ?details) (?typeLabel AS ?hazardTypeName)
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  ?hazardEvent kwgl-ont:hasHazardType ?hazardType .

  OPTIONAL { ?hazardType rdfs:label ?typeLabel . }

  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?value . BIND(CONCAT("Affected Area in Acres: ", STR(?value)) AS ?detailProperty) }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?value . BIND(CONCAT("Damage to Crops in Dollars: ", STR(?value)) AS ?detailProperty) }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?value . BIND(CONCAT("Damage to Infrastructure in Dollars: ", STR(?value)) AS ?detailProperty) }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?value . BIND(CONCAT("Number of Deaths: ", STR(?value)) AS ?detailProperty) }
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name . BIND(CONCAT("Name: ", STR(?name)) AS ?detailProperty) }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?date . BIND(CONCAT("Start Date: ", STR(?date)) AS ?detailProperty) }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?date . BIND(CONCAT("End Date: ", STR(?date)) AS ?detailProperty) }

}
GROUP BY ?hazardType ?typeLabel

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?event ?eventName ?startDate ?endDate
  (GROUP_CONCAT(DISTINCT ?damageType; SEPARATOR=", ") AS ?impactFactors)
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:hasName ?eventName . }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate . }

  {
    SELECT ?event ?damageType WHERE {
      {
        ?event kwgl-ont:affectedAreaInAcres ?value .
        BIND(STR(?event) AS ?damageType)
      } UNION {
        ?event kwgl-ont:damageToCropsInDollars ?value .
        BIND("Damage to crops in dollars" AS ?damageType)
      } UNION {
        ?event kwgl-ont:damageToInfrastructureInDollars ?value .
        BIND("Damage to infrastructure in dollars" AS ?damageType)
      } UNION {
        ?event kwgl-ont:numberOfDeaths ?value .
        BIND("Number of deaths" AS ?damageType)
      }
    }
  }
}
GROUP BY ?event ?eventName ?startDate ?endDate

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?placeName ?startDate ?endDate ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Tornado ;
               kwgl-ont:hasStartDate ?startDate ;
               kwgl-ont:hasEndDate ?endDate .
  ?hazardEvent kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
}
ORDER BY ?placeName

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardEvent ?place ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
    ?hazardEvent rdf:type kwgl-ont:Hurricane .
    ?hazardEvent kwgl-ont:hasImpacted ?place .
    OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
    OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue WHERE {
  ?publication coresr-ont:hasIdentifier ?doi .
  ?doi coresr-ont:doiAsString ?doiValue .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?typeString WHERE {
  ?publication coresr-ont:hasPublicationType ?type .
  ?type coresr-ont:typeAsString ?typeString .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?title ?fieldOfStudy
WHERE {
  ?publication coresr-ont:hasTitle ?title .
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS { ?agent coresr-ont:hasContactInformation ?contactInfo . ?contactInfo coresr-ont:nameAsString ?familyName . }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX terms: <http://purl.org/dc/terms/>
SELECT DISTINCT ?author WHERE {
  ?ontology terms:contributor ?author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?department WHERE {
  ?department rdf:type coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor WHERE {
  ?author a coresr-ont:Author ;
          coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?agent ?department WHERE {
  ?agent rdf:type coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?fieldOfStudy ?publicationTitle WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
  ?publication coresr-ont:hasTitle ?publicationTitle .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
SELECT ?publication WHERE {
  ?publication rdf:type coresr-ont:Publication .
  ?contributor1 rdf:type coresr-ont:Contributor ;
                coresr-ont:contributedTo ?publication ;
                coresr-ont:isPerformedBy ?agent1 .
  ?department1 coresr-ont:associatedWith ?agent1 .
  ?contributor2 rdf:type coresr-ont:Contributor ;
                coresr-ont:contributedTo ?publication ;
                coresr-ont:isPerformedBy ?agent2 .
  ?department2 coresr-ont:associatedWith ?agent2 .
  FILTER(?department1 != ?department2)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationType (AVG(?timeDifference) AS ?avgTimeDifference)
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasPublicationType ?publicationType ;
               coresr-ont:dateOfSubmission ?submissionDate ;
               coresr-ont:dateOfPublication ?publicationDate .
  BIND(xsd:integer(?publicationDate - ?submissionDate) AS ?timeDifference)
}
GROUP BY ?publicationType
ORDER BY DESC(?avgTimeDifference)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS { ?agent coresr-ont:hasContactInformation ?contactInfo . ?contactInfo a coresr-ont:FamilyName }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationTitle ?doiValue WHERE {
  ?publication coresr-ont:hasTitle ?publicationTitle ;
              coresr-ont:hasIdentifier ?doi .
  ?doi coresr-ont:doiAsString ?doiValue .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department WHERE {
  ?department a coresr-ont:Department.
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publicationTitle ?submissionDate WHERE {
  ?publication coresr-ont:hasTitle ?publicationTitle .
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?universityName ?cityName WHERE {
  ?university a coresr-ont:University .
  ?university coresr-ont:locatedAt ?location .
  ?location coresr-ont:isStateOf ?state .
  ?state coresr-ont:inCity ?city .
  ?city coresr-ont:nameAsString ?cityName .
  OPTIONAL { ?university coresr-ont:nameAsString ?universityName . }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?advisor ?author WHERE {
  ?advisor coresr-ont:advises ?author .
  ?advisor a coresr-ont:Advisor .
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department WHERE {
  ?agent a coresr-ont:Agent .
  ?department a coresr-ont:Department .
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?city ?university ?college WHERE {
  ?location a coresr-ont:Location ;
            coresr-ont:isStateOf ?state .
  ?state coresr-ont:inCity ?city .
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location ;
              coresr-ont:hasPart ?college .
  ?college a coresr-ont:College .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?university (COUNT(?publication) AS ?publicationCount)
WHERE {
  ?location a coresr-ont:Location ;
            coresr-ont:atState ?state ;
            coresr-ont:isLocationOf ?university .
  ?university a coresr-ont:University ;
              coresr-ont:locatedAt ?location .
  ?publication a coresr-ont:Publication ;
               coresr-ont:submittedBy ?author .
  ?author a coresr-ont:Author ;
          coresr-ont:associatedWith ?department .
  ?department a coresr-ont:Department ;
              coresr-ont:partOf ?college .
  ?college a coresr-ont:College ;
           coresr-ont:partOf ?university .
}
GROUP BY ?state ?university
ORDER BY DESC(?publicationCount) ?state ?university

