PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?hazardEvent ?hazardType ?startDate ?endDate ?damageToInfrastructureInDollars ?numberOfDeaths ?affectedAreaInAcres
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  ?hazardEvent kwgl-ont:hasHazardType ?hazardType .
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
}
ORDER BY ?hazardEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?place ?concern
WHERE {
  ?place rdf:type kwgl-ont:Place .
  {
    ?concern rdf:type owl:DatatypeProperty .
    ?concern rdfs:domain kwgl-ont:Place .
  } UNION {
    ?concern rdf:type owl:ObjectProperty .
    ?concern rdfs:domain kwgl-ont:Place .
  }
  ?place ?concern ?value .
}
ORDER BY ?place ?concern

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?attribute ?count
WHERE {
  {
    SELECT ?attribute (COUNT(DISTINCT ?place) AS ?count)
    WHERE {
      ?attribute rdf:type owl:DatatypeProperty .
      ?place kwgl-ont:impactedBy [kwgl-ont:hasHazardType kwglr:tornado] .
      ?place ?attribute ?value .
    }
    GROUP BY ?attribute
  }
}
ORDER BY DESC(?count)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?hazardEvent ?hazardTypeLabel ?endDate ?startDate ?name
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazardType rdfs:label ?hazardTypeLabel . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name . }

}
ORDER BY ?hazardEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?event ?type ?affectedArea ?damageToCrops ?damageToInfrastructure ?numberOfDeaths
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardEvent ?damageDetail
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?area . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropsDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deathsCount . }

  BIND (GROUP_CONCAT(DISTINCT (
    IF(BOUND(?area), CONCAT("Affected Area: ", STR(?area)), "") ||
    IF(BOUND(?cropsDamage), CONCAT("Crops Damage: $", STR(?cropsDamage)), "") ||
    IF(BOUND(?infrastructureDamage), CONCAT("Infrastructure Damage: $", STR(?infrastructureDamage)), "") ||
    IF(BOUND(?deathsCount), CONCAT("Deaths Count: ", STR(?deathsCount)), "")
  ); separator=" | ") AS ?damageDetail)
}
ORDER BY ?hazardEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?hazardAttribute
  ?hazardAttributeLabel
  ?damageImpactDetail
  ?temporalData
WHERE {
  { # Hurricane-specific hazard attributes related to a geographical place
    ?place rdf:type kwgl-ont:Place .
    ?hurricane rdf:type kwgl-ont:Hurricane ;
              kwgl-ont:hasImpacted ?place .

    OPTIONAL { ?place ?hazardAttribute ?value . }
    OPTIONAL { ?hazardAttribute rdfs:label ?hazardAttributeLabel . }

    FILTER (CONTAINS(LCASE(STR(?hurricane)), "hurricane"))
  } UNION {
    # Damage impact details and temporal data
    ?place rdf:type kwgl-ont:Place .
    ?hurricane rdf:type kwgl-ont:Hurricane ;
              kwgl-ont:hasImpacted ?place .

    OPTIONAL { ?hurricane kwgl-ont:damageToCropsInDollars ?damageToCrops . }
    OPTIONAL { ?hurricane kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
    OPTIONAL { ?hurricane kwgl-ont:numberOfDeaths ?numberOfDeaths . }
    OPTIONAL { ?hurricane kwgl-ont:hasStartDate ?startDate . }
    OPTIONAL { ?hurricane kwgl-ont:hasEndDate ?endDate . }

    BIND(COALESCE(?damageToCrops, ?damageToInfrastructure, ?numberOfDeaths) AS ?damageImpactDetail)
    BIND(COALESCE(?startDate, ?endDate) AS ?temporalData)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?tornadoEvent ?placeName ?startDate ?endDate ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?tornadoEvent rdf:type kwgl-ont:Tornado .
  ?tornadoEvent kwgl-ont:hasHazardType kwglr:tornado .

  ?place kwgl-ont:impactedBy ?tornadoEvent .
  ?place kwgl-ont:hasName ?placeName .
  OPTIONAL { ?place kwgl-ont:sfWithin ?widerPlace . }
  OPTIONAL { ?place kwgl-ont:sfOverlaps ?overlapPlace . }

  ?tornadoEvent kwgl-ont:hasStartDate ?startDate .
  ?tornadoEvent kwgl-ont:hasEndDate ?endDate .

  OPTIONAL { ?tornadoEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?tornadoEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }

}
ORDER BY ?placeName

