PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?state ?university (COUNT(?publication) AS ?publicationCount)
WHERE {
  ?university rdf:type coresr-ont:University .
  ?location rdf:type coresr-ont:Location ;
             coresr-ont:isLocationOf ?university ;
             coresr-ont:atState ?state .
  ?publication rdf:type coresr-ont:Publication ;
               coresr-ont:submittedBy ?author .
  ?agent rdf:type coresr-ont:Agent ;
         coresr-ont:performsRole ?author ;
         coresr-ont:associatedWith ?department .
  ?department rdf:type coresr-ont:Department ;
              coresr-ont:partOf ?college .
  ?college rdf:type coresr-ont:College ;
           coresr-ont:partOf ?university .
