SELECT ?department (COUNT(?agent) AS ?count)
WHERE {
  ?department a coresr-ont:Department .
  ?agent a coresr-ont:Agent ;
          coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS { ?agent coresr-ont:hasContactInformation ?contactInfo . ?contactInfo coresr-ont:nameAsString ?familyName . FILTER(BOUND(?familyName)) }
}
GROUP BY ?department
ORDER BY DESC(?count)
