WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS { ?agent coresr-ont:hasContactInformation ?contactInfo . ?contactInfo coresr-ont:nameAsString ?familyName . }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazardType ?property ?value ?temporalScope
WHERE {
  ?hazard a kwg-ont:Hazard ;
          rdfs:subClassOf* ?hazardType .
  OPTIONAL { ?hazardType rdfs:subClassOf ?superType . }
  OPTIONAL { ?hazard ?property ?value . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . }
}
ORDER BY ?hazardType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/># Assuming a placeholder for USGS prefix

SELECT DISTINCT ?geographicalPlace ?name
WHERE {
  {
    ?geographicalPlace rdfs:subClassOf* kwg-ont:AdministrativeRegion .
    ?geographicalPlace rdfs:label ?name .
  }
  UNION
  {
    ?geographicalPlace rdfs:subClassOf* usgs:Terrain .
    ?geographicalPlace rdfs:label ?name .
  }
  UNION
  {
    ?geographicalPlace rdfs:subClassOf* usgs:SurfaceWater .
    ?geographicalPlace rdfs:label ?name .
  }
  UNION
  {
    ?geographicalPlace rdfs:subClassOf* kwg-ont:Region .
    ?geographicalPlace rdfs:label ?name .
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?healthConcern ?healthAttribute WHERE {
  {
    ?healthConcern a kwg-ont:Hospital .
    ?healthConcern rdfs:subClassOf* ?concernType .
    OPTIONAL { ?concernType rdfs:subClassOf ?superType . }
    OPTIONAL { ?concernType ?property ?value . }
  } UNION {
    ?healthAttribute a kwg-ont:HealthCareFacility .
    ?healthAttribute rdfs:subClassOf* ?attributeType .
    OPTIONAL { ?attributeType rdfs:subClassOf ?superType . }
    OPTIONAL { ?attributeType ?property ?value . }
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>

SELECT DISTINCT ?stormAttribute ?attributeValue
WHERE {
  {
    ?hazard rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
    FILTER (REGEX(STR(?hazard), "Storm", "i")) .
    OPTIONAL { ?hazard ?property ?value . BIND(CONCAT(str(?property), " - ", str(?value)) AS ?stormAttribute) . }
  } UNION {
    kwg-ont:StormTrackObservableProperty a ?observablePropertyClass .
    ?observablePropertyClass rdfs:subClassOf* sosa:ObservableProperty .
    OPTIONAL { ?observablePropertyClass ?property ?value . BIND(CONCAT(str(?property), " - ", str(?value)) AS ?stormAttribute) . }
  } UNION {
    kwg-ont:StormTrackletObservableProperty a ?trackletObservablePropertyClass .
    ?trackletObservablePropertyClass rdfs:subClassOf* sosa:ObservableProperty .
    OPTIONAL { ?trackletObservablePropertyClass ?property ?value . BIND(CONCAT(str(?property), " - ", str(?value)) AS ?stormAttribute) . }
  }

  # Retrieve all storm-related attributes and values associated with geographical places
  ?place a kwg-ont:AdministrativeRegion ;
          kwg-ont:hasGeometry geo:Geometry ;
          geo:hasDefaultGeometry geo:Geometry .
  OPTIONAL { ?place ?spatialRelation ?hazard . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?floodHazardType ?property ?value
WHERE {
  ?floodHazardType rdfs:subClassOf* kwg-ont:NOAAFlood .
  OPTIONAL { ?floodHazardType ?property ?value . }
}
ORDER BY ?floodHazardType ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
