SELECT DISTINCT ?attribute ?value WHERE {
  {
    SELECT DISTINCT ?attribute ?value WHERE {
      ?geographicalPlace rdf:type geo:Feature .
      ?geographicalPlace ?property ?value .
      VALUES (?property) {(kwgr:climateObservableProperty.CDD) (kwgr:climateObservableProperty.HDD)
                          (kwgr:climateObservableProperty.PDSI) (kwgr:climateObservableProperty.PHDI)
                          (kwgr:climateObservableProperty.PMDI) (kwgr:climateObservableProperty.PZI)
                          (kwgr:climateObservableProperty.avgTemp) (kwgr:climateObservableProperty.maxTemp)
                          (kwgr:climateObservableProperty.minTemp) (kwgr:climateObservableProperty.precipitation)}
      BIND(?property AS ?attribute) .
    }
  } UNION {
    SELECT DISTINCT ?attribute ?value WHERE {
      ?geographicalPlace rdf:type kwg-ont:USClimateDivision .
      ?geographicalPlace ?property ?value .
      VALUES (?property) {(kwgr:climateDivisionFIPS) (kwgr:climateDivisionNCDC_GEO)
                          (kwgr:climateDivisionName) (kwgr:climateDivisionNumber)}
      BIND(?property AS ?attribute) .
