      VALUES (?property) {(kwgr:nifcFireObservableProperty.calculatedAcres)
                          (kwgr:nifcFireObservableProperty.fireDiscoveryDateTime)
                          (kwgr:nifcFireObservableProperty.fireOutDateTime)}
      BIND(?property AS ?attribute) .
