    SELECT DISTINCT ?attribute ?value WHERE {
      ?geographicalPlace rdf:type kwg-ont:Earthquake .
      ?geographicalPlace ?property ?value .
      VALUES (?property) {(kwgr:earthquakeObservableProperty.depth)
                          (kwgr:earthquakeObservableProperty.depthError)
