PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeHazardType ?subClassOf ?property ?value
WHERE {
  ?earthquakeHazardType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeHazardType rdfs:subClassOf ?subClassOf . }
  OPTIONAL { ?earthquakeHazardType ?property ?value . }
}
ORDER BY ?earthquakeHazardType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?impactFactorDetail
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  ?observationCollection a kwg-ont:ImpactObservationCollection ;
                          sosa:hasFeatureOfInterest ?hazardEvent ;
                          sosa:phenomenonTime ?timeEntity ;
                          sosa:hasMember ?impactObservation .

  ?impactObservation a sosa:Observation ;
                      sosa:observedProperty ?impactObservableProperty ;
                      kwg-ont:value ?value .

  OPTIONAL { ?impactObservableProperty rdfs:label ?impactFactorDetail . }
}
ORDER BY ?impactFactorDetail

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sf: <http://www.opengis.net/ont/sf#>

SELECT ?hazardAttribute ?attributeValue ?damageImpactDetail ?temporalData WHERE {
  # Hurricane-specific hazard attributes
  ?hurricaneType rdfs:subClassOf* kwg-ont:NOAAHurricane .
  ?hazardAttribute a ?type ;
                      kwg-ont:hasGeometry ?geometry ;
                      kwg-ont:spatialRelation ?geographicalPlace .

  OPTIONAL { ?hazardAttribute ?property ?attributeValue . }

  # Damage impact details
  OPTIONAL {
    ?damageImpactDetail a kwg-ont:ImpactObservationCollection .
    ?damageImpactDetail sosa:hasMember ?impactObservation .
    ?impactObservation sosa:observedProperty ?impactObservableProperty .
    ?impactObservableProperty rdfs:subClassOf* kwg-ont:ImpactObservableProperty .

    OPTIONAL { ?damageImpactDetail sosa:phenomenonTime ?temporalData . }
  }

  # Temporal data
  OPTIONAL {
    ?hurricaneEvent a kwg-ont:NOAAHurricane .
    ?hurricaneEvent time:hasTemporalScope ?temporalEntity .
    BIND(?temporalEntity AS ?temporalData) .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardEvent ?hazardType ?hasStartDate ?hasEndDate ?damageToInfrastructureInDollars WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  ?hazardEvent kwgl-ont:hasHazardType ?hazardType .
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?hasStartDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?hasEndDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?healthConcern
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?healthConcern . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?healthConcern . }
  OPTIONAL { ?place kwgl-ont:percentObese ?healthConcern . }
  FILTER(isLiteral(?healthConcern))
}
ORDER BY ?place

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?attribute (COUNT(?place) AS ?count)
WHERE {
  {
    SELECT DISTINCT ?attribute WHERE {
      ?attribute rdf:type owl:DatatypeProperty .
      FILTER (
        CONTAINS(LCASE(STR(?attribute)), "tornado") ||
        CONTAINS(LCASE(SUBSTR(STR(?attribute), STRLEN("http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/") + 1)), "tornado")
      )
    }
  }

  ?place a kwgl-ont:Place .
  ?place ?attribute ?value .

}
GROUP BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?attribute
WHERE {
  VALUES ?hurricane {
    kwgl-ont:Hurricane
  }

  ?attribute a owl:DatatypeProperty ;
             rdfs:domain ?place .

  ?place a kwgl-ont:Place ;
         kwgl-ont:impactedBy ?event .

  ?event a kwgl-ont:HazardEvent ;
         rdf:type ?hurricane .
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?attribute WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?hazardType ?hazardTypeLabel
WHERE {
  {
    SELECT DISTINCT ?hazardType WHERE {
      ?hazardType rdf:type owl:NamedIndividual .
      ?hazardType a kwgl-ont:HazardType .
    }
  }

  OPTIONAL { ?hazardType rdfs:label ?hazardTypeLabel . }
  FILTER(CONTAINS(LCASE(STR(?hazardType)), "earthquake"))
}
ORDER BY ?hazardType

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?hazardType ?damageProperty ?damageValue WHERE {
  ?place a owl:Thing .
  ?hazardEvent a kwgl-ont:HazardEvent .
  ?hazardEvent kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?damageValue . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damageValue . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageValue . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?damageValue . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?damageValue . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageValue . }

  BIND(COALESCE(?dollarDamageOfFiresImpactingPlace, ?dollarDamageOfFloodsImpactingPlace,
                ?dollarDamageOfHurricanesImpactingPlace, ?dollarDamageOfLandslidesImpactingPlace,
                ?dollarDamageOfStormSurgesImpactingPlace, ?dollarDamageOfTornadoesImpactingPlace)
        AS ?damageValue)

  BIND(COALESCE(
      IF(BOUND(?dollarDamageOfFiresImpactingPlace), "Fire Damage", undefined),
      IF(BOUND(?dollarDamageOfFloodsImpactingPlace), "Flood Damage", undefined),
      IF(BOUND(?dollarDamageOfHurricanesImpactingPlace), "Hurricane Damage", undefined),
      IF(BOUND(?dollarDamageOfLandslidesImpactingPlace), "Landslide Damage", undefined),
      IF(BOUND(?dollarDamageOfStormSurgesImpactingPlace), "Storm Surge Damage", undefined),
      IF(BOUND(?dollarDamageOfTornadoesImpactingPlace), "Tornado Damage", undefined)
    ) AS ?damageProperty)

  FILTER(BOUND(?hazardType) && BOUND(?damageValue))
}

