PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>

SELECT DISTINCT ?place ?name WHERE {
  { ?place rdf:type geo:Feature .
    OPTIONAL { ?place rdfs:label ?name . }
  } UNION
  { ?place rdf:type gnis:State .
    OPTIONAL { ?place gnis:stateName ?name . }
  } UNION
  { ?place rdf:type usgs:Feature .
    OPTIONAL { ?place rdfs:label ?name . }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?concern
WHERE {
  ?place a geo:Feature ;
         kwg-ont:spatialRelation ?region .
  ?region kwg-ont:hasTemporalScope ?temporalEntity .
  ?hazard a kwg-ont:Hazard ;
          geo:hasGeometry ?geometry ;
          kwg-ont:spatialRelation ?region ;
          kwg-ont:hasTemporalScope ?temporalEntity .
  ?concern a sosa:ObservableProperty ;
           rdfs:subClassOf* kwg-ont:VulnerabilityObservableProperty .
  ?observation a sosa:Observation ;
               sosa:observedProperty ?concern ;
               sosa:hasFeatureOfInterest ?hazard ;
               sosa:phenomenonTime ?temporalEntity .
}

PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?demographicAttribute WHERE {
  VALUES ?observableProperty { kwgr:censusObservableProperty.totalPopulation
                               kwgr:censusObservableProperty.malePopulation
                               kwgr:censusObservableProperty.femalePopulation
                               kwgr:censusObservableProperty.householdUnits }
  ?observableProperty rdfs:subClassOf ?demographicAttribute .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardEvent ?impactFactor
WHERE {
  ?hazardEvent rdfs:subClassOf kwg-ont:NOAAHazardEvent .
  ?impactObservation sosa:hasFeatureOfInterest ?hazardEvent ;
                     sosa:observedProperty ?impactObservableProperty ;
                     sosa:hasSimpleResult ?impactFactor .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?damageDetail WHERE {
  ?impactObservation a kwg-ont:ImpactObservation ;
                      sosa:observedProperty ?observableProperty ;
                      sosa:hasSimpleResult ?damageDetail .
  ?observableProperty rdfs:subClassOf kwg-ont:ImpactObservableProperty .
}

PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardAttribute ?damageImpactDetail ?temporalData WHERE {
  ?hazard a kwg-ont:NOAAHurricane .
  ?hazard geo:hasGeometry ?geometry .
  ?hazard sosa:observedProperty ?observableProperty .
  ?observableProperty rdfs:subClassOf* kwgr:magnitudeObservableProperty.* .

  OPTIONAL {
    ?impactObservation a sosa:ImpactObservation ;
                      sosa:observedProperty ?impactObservableProperty ;
                      sosa:hasSimpleResult ?damageImpactDetail .
    ?impactObservableProperty rdfs:subClassOf* kwgr:impactObservableProperty.* .
  }

  OPTIONAL {
    ?hazard time:hasTemporalScope/time:hasBeginning ?temporalData .
    FILTER (isLiteral(?temporalData)) .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?damageDetails WHERE {
  ?hazardEvent a kwg-ont:NOAATornado ;
              geo:hasGeometry ?geometry ;
              time:hasTemporalScope ?temporalExtent ;
              sosa:hasFeatureOfInterest ?geographicalPlace .

  ?impactObservation sosa:observedProperty ?impactObservableProperty ;
                    sosa:hasSimpleResult ?damageDetails ;
                    sosa:phenomenonTime ?temporalExtent ;
                    sosa:hasFeatureOfInterest ?hazardEvent .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?damageDetails WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
              geo:hasGeometry ?geometry ;
              time:hasTemporalScope ?temporalExtent .
  ?impactObservation sosa:hasFeatureOfInterest ?hazardEvent ;
                     sosa:observedProperty ?observableProperty ;
                     sosa:hasSimpleResult ?damageDetails .
  ?observableProperty rdfs:subClassOf kwg-ont:ImpactObservableProperty .
}

