  ?author rdf:type coress-ont:Author ;
          coress-ont:submits ?publication .
  ?agent rdf:type coress-ont:Agent ;
         coress-ont:performsRole ?author .
  ?department rdf:type coress-ont:Department ;
              coress-ont:hasAgent ?agent .
  ?college rdf:type coress-ont:College ;
           coress-ont:hasDepartment ?department .
  ?university coress-ont:hasCollege ?college .
}
