PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?title
WHERE {
  ?publication coresr-ont:hasTitle ?title .
  ?contributor1 coresr-ont:contributedTo ?publication ;
               coresr-ont:associatedWith ?department1 .
  ?contributor2 coresr-ont:contributedTo ?publication ;
               coresr-ont:associatedWith ?department2 .
  FILTER(?department1 != ?department2)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS { ?agent coresr-ont:hasContactInformation ?contactInfo . ?contactInfo coresr-ont:nameAsString ?familyName . }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?hazardType ?property ?value ?temporalScope
WHERE {
  ?hazard rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazard a ?hazardType . }
  OPTIONAL { ?hazard ?property ?value . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . }
}
ORDER BY ?hazard ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?placeName
WHERE {
  {
    ?place rdfs:label ?placeName .
    FILTER (CONTAINS(STR(?place), "AdministrativeRegion"))
  } UNION {
    ?place rdfs:label ?placeName .
    FILTER (CONTAINS(STR(?place), "NWZone"))
  } UNION {
    ?place rdfs:label ?placeName .
    FILTER (CONTAINS(STR(?place), "FederalJudicalDistrict"))
  } UNION {
    ?place rdfs:label ?placeName .
    FILTER (CONTAINS(STR(?place), "USCensusMSA"))
  } UNION {
    ?place rdfs:label ?placeName .
    FILTER (CONTAINS(STR(?place), "NielsenMarketZone"))
  }
}
ORDER BY ?placeName

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?healthConcern ?property ?value
WHERE {
  ?place a kwg-ont:AdministrativeRegion .
  OPTIONAL { ?place rdfs:subClassOf* ?healthConcern . }
  OPTIONAL { ?healthConcern ?property ?value . }
}
ORDER BY ?healthConcern ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazardAttribute ?property ?value
WHERE {
  ?stormHazardType rdfs:subClassOf* kwg-ont:StormTrack .
  OPTIONAL { ?stormHazardType ?property ?value . }
}
ORDER BY ?hazardAttribute ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?impactFactor ?value
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent .
  ?observationCollection a kwg-ont:ImpactObservationCollection ;
                        sosa:hasFeatureOfInterest ?hazardEvent ;
                        sosa:hasMember ?observation .
  ?observation a kwg-ont:ImpactObservation ;
               sosa:observedProperty ?impactFactor ;
               sosa:hasResult ?result .
  ?result a sosa:Result ;
          rdfs:value ?value .
}
ORDER BY ?hazardEvent ?impactFactor

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardAttribute ?damageImpactDetail ?temporalData
WHERE {
  ?hurricane a kwg-ont:NOAAHurricane .
  ?hurricane sosa:isFeatureOfInterestOf ?impactObservationCollection .
  ?impactObservationCollection a kwg-ont:ImpactObservationCollection ;
                              sosa:hasMember ?impactObservation .

  OPTIONAL {
    ?impactObservation sosa:observedProperty ?hazardAttribute .
    ?hazardAttribute rdfs:subClassOf* kwg-ont:NOAAHurricane .
  }

  OPTIONAL {
    ?impactObservationCollection sosa:phenomenonTime ?temporalData .
    ?temporalData a time:TemporalEntity .
  }

  OPTIONAL {
    ?impactObservation sosa:observedProperty ?damageImpactDetail .
    ?damageImpactDetail rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
  }
}
ORDER BY ?hazardAttribute ?damageImpactDetail

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?hazardType ?hazardName ?hazardDetail ?eventTime
WHERE {
  {
    SELECT ?hazardType (GROUP_CONCAT(DISTINCT ?name; separator="|") AS ?hazardName) (GROUP_CONCAT(DISTINCT ?detail; separator="|") AS ?hazardDetail) (GROUP_CONCAT(DISTINCT ?time; separator="|") AS ?eventTime)
    WHERE {
      {
        SELECT ?hazardType ?hazard ?detail
        WHERE {
          {
            SELECT ?hazardType
            WHERE {
              ?hazardType rdfs:subClassOf* kwg-ont:Hazard .
            }
          }
          ?hazard a ?hazardType .
          OPTIONAL { ?hazard kwgr:name ?name . }
          OPTIONAL { ?hazard kwgr:description ?detail . }
        }
      }
      UNION
      {
        SELECT ?hazardType ?hazard ?time
        WHERE {
          {
            SELECT ?hazardType
            WHERE {
              ?hazardType rdfs:subClassOf* kwg-ont:Hazard .
            }
          }
          ?hazard a ?hazardType .
          OPTIONAL { ?hazard kwg-ont:hasTemporalScope/time:inXSDDateTime ?time . }
        }
      }
    }
    GROUP BY ?hazardType
  }
}
ORDER BY ?hazardType

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>

SELECT DISTINCT ?placeName ?healthConcern
WHERE {
  {
    SELECT ?place (GROUP_CONCAT(DISTINCT ?propertyName; separator=" | ") AS ?concernNames) AS ?concerns WHERE {
      {
        SELECT ?place WHERE {
          { ?place rdfs:subClassOf kwg-ont:HealthCareFacility . }
          UNION
          { ?place rdf:type kwg-ont:Hospital . }
        }
      }
      OPTIONAL { ?property sosa:observedProperty ?observedProperty .
                 ?healthConcernType rdfs:subPropertyOf ?observedProperty .
                 FILTER(CONTAINS(str(?healthConcernType), "publicHealth")) .
                 BIND(REPLACE(str(?property), "^http://stko-kwg.geog.ucsb.edu/lod/resource/", "") AS ?concernNames) }
      OPTIONAL { ?property sosa:observedProperty ?observableProperty .
                 ?healthConcernType rdfs:subClassOf ?observableProperty .
                 FILTER(CONTAINS(str(?healthConcernType), "publicHealth")) .
                 BIND(REPLACE(str(?property), "^http://stko-kwg.geog.ucsb.edu/lod/resource/", "") AS ?concernNames) }
    } GROUP BY ?place
  }

  OPTIONAL { ?place rdfs:label ?placeName . FILTER(LANG(?placeName) = "en") }
  BIND(STRDT(?concerns, xsd:string) as ?healthConcern)
}

PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX qudt: <http://qudt.org/1.1/schema/qudt#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX cdt: <https://w3id.org/cdat#>

SELECT DISTINCT ?demographicAttribute ?value
WHERE {
  {
    ?place rdf:type kwg-ont:AdministrativeRegion .
    OPTIONAL { ?place ?demographicAttribute ?value . }
  } UNION {
    ?place rdf:type usgs:BuiltUpArea .
    OPTIONAL { ?place ?demographicAttribute ?value . }
  } UNION {
    ?place rdf:type kwg-ont:Hospital .
    OPTIONAL { ?place ?demographicAttribute ?value . }
  } UNION {
    ?place rdf:type usgs:Terrain .
    OPTIONAL { ?place ?demographicAttribute ?value . }
  } UNION {
    ?place rdf:type usgs:SurfaceWater .
    OPTIONAL { ?place ?demographicAttribute ?value . }
  }

  # Include specific demographic attributes like population, household units, etc.
  VALUES (?expectedAttribute) {
    (kwgr:censusObservableProperty.totalPopulation)
    (kwgr:censusObservableProperty.malePopulation)
    (kwgr:censusObservableProperty.femalePopulation)
    (kwgr:censusObservableProperty.householdUnits)
  }

  FILTER(?demographicAttribute = ?expectedAttribute)

}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attributeType
WHERE {
  VALUES (?type) {(kwg-ont:NOAATornado)}
  ?type rdfs:subClassOf* kwg-ont:Hazard .
  ?type ?p ?o .
  BIND(REPLACE(STR(?p), "http://stko-kwg.geog.ucsb.edu/lod/ontology/", "") AS ?attributeType)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazardType ?property ?value
WHERE {
  ?hazardType rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazardType ?property ?value . }
}
ORDER BY ?hazardType ?property

PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX qudt: <http://qudt.org/1.1/schema/qudt#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX cdt: <http://stko-kwg.geog.ucsb.edu/lod/dataset/>

SELECT DISTINCT ?property ?value
WHERE {
  { ?geoplace rdfs:subClassOf* kwg-ont:Region .
    OPTIONAL { ?geoplace kwg-ont:spatialRelation ?s2cell . }
    FILTER NOT EXISTS { ?s2cell geo:hasDefaultGeometry [] . }
  } UNION
  { ?geoplace rdfs:subClassOf* usgs:Division .
    OPTIONAL { ?geoplace kwg-ont:sfWithin ?s2cell . }
  } UNION
  { ?geoplace rdfs:subClassOf* usgs:Terrain .
    OPTIONAL { ?geoplace geo:hasGeometry [] . }
  } UNION
  { ?geoplace rdfs:subClassOf* usgs:SurfaceWater .
    OPTIONAL { ?geoplace kwg-ont:spatialRelation ?s2cell . }
    FILTER NOT EXISTS { ?s2cell geo:hasDefaultGeometry [] . }
  }

  ?geoplace ?property ?value .
  FILTER(?property IN (kwg-ont:zoneNumber, kwg-ont:zoneName, gnis:elevation, qudt:value, rdfs:label, sosa:hasABBR) )
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardAttribute ?attributeValue
WHERE {
  {
    # Hurricane-specific hazard attributes related to a geographical place
    ?hurricane rdf:type kwg-ont:NOAAHurricane .
    ?hurricane kwg-ont:spatialRelation ?geoPlace .
    ?geoPlace rdfs:subClassOf* geo:Feature .
    OPTIONAL { ?hurricane ?property ?value . }
  } UNION {
    # Damage impact details and temporal data
    ?hazardEvent rdf:type kwg-ont:NOAAHurricane .
    ?impactObservation sosa:hasFeatureOfInterest ?hazardEvent ;
                     sosa:observedProperty kwg-ont:ImpactObservableProperty ;
                     sosa:resultTime ?temporalData .
    OPTIONAL { ?impactObservation ?property ?value . }
  }

  # Filter out duplicates
  BIND(COALESCE(?property, "unknown") AS ?hazardAttribute)
  BIND(COALESCE(STR(?value), "no value available") AS ?attributeValue)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?hazardType ?damageDetails ?geoLocation ?temporalExtent
WHERE {
  ?hazard rdf:type kwg-ont:Hazard .
  ?hazard rdfs:subClassOf* ?hazardType .
  OPTIONAL { ?hazard kwg-ont:spatialRelation ?geoLocation . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalExtent . }

  # Damage details
  OPTIONAL {
    FILTER(isBlank(?hazard))
    BIND(strafter(str(?hazard), strdnto:blankNode) AS ?damageDetails)
  }
  OPTIONAL { ?hazard kwg-ont:hasDamageDetails ?damageDetails . }

  # Filter for storm-specific hazards
  VALUES ?stormHazards {
    (kwg-ont:NOAAThunderstormWind)
    (kwg-ont:NOAATornado)
    (kwg-ont:NOAAWildfire)
    (kwg-ont:NOAAMarineStrongWind)
    (kwg-ont:NOAAStrongWind)
  }
  FILTER(?hazardType IN ?stormHazards)

}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT ?hazardEvent ?hasHazardType ?hasName ?hasStartDate ?hasEndDate ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hasName . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?hasStartDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?hasEndDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  ?hazardEvent kwgl-ont:hasHazardType ?hasHazardType .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?place ?healthAttribute WHERE {
  ?place rdf:type kwgl-ont:Place .
  {
    ?place kwgl-ont:percentBelowPovertyLine ?healthAttribute .
  } UNION {
    ?place kwgl-ont:percentDiabetic ?healthAttribute .
  } UNION {
    ?place kwgl-ont:percentObese ?healthAttribute .
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?attribute (COUNT(?attribute) AS ?count)
WHERE {
  { kwgl-ont:Tornado rdfs:subClassOf ?attribute . }
  UNION
  { ?attribute rdfs:subPropertyOf ?property .
    ?property rdfs:domain kwgl-ont:Tornado .
  }
}
GROUP BY ?attribute

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardType ?place ?damageToInfrastructureInDollars ?damageToCropsInDollars ?affectedAreaInAcres
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  ?event kwgl-ont:hasHazardType ?hazardType .
  ?event kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  FILTER CONTAINS(str(?hazardType), "storm")
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardAttribute ?placeName WHERE {
    ?place a kwgl-ont:Place ;
           kwgl-ont:hasName ?placeName .

    ?flood a kwgl-ont:HazardEvent ;
