SELECT DISTINCT ?hazard ?typeDetails WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?hazardType .
              ?hazardType rdfs:label ?typeDetails . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?placeName ?hazardEventName ?damageToInfrastructureInDollars ?damageToCropsInDollars ?numberOfDeaths ?startDate ?endDate
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Tornado ;
              kwgl-ont:hasHazardType kwglr:tornado ;
              kwgl-ont:hasImpacted ?place ;
              kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars ;
              kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars ;
              kwgl-ont:numberOfDeaths ?numberOfDeaths ;
              kwgl-ont:hasStartDate ?startDate ;
              kwgl-ont:hasEndDate ?endDate .
  ?place kwgl-ont:hasName ?placeName .
  ?hazardEvent kwgl-ont:hasName ?hazardEventName .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author
WHERE {
  ?author a coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?submissionDate WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?advisor WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?publicationType
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?publicationType .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?agent ?department WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?fieldOfStudy ?publication
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?city ?university ?college WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
  ?university coress-ont:hasCollege ?college .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication
WHERE {
  ?publication a coress-ont:Publication .
  ?author1 a coress-ont:Author ;
           coress-ont:submits ?publication ;
           coress-ont:worksInDepartment ?department1 .
  ?author2 a coress-ont:Author ;
           coress-ont:submits ?publication ;
           coress-ont:worksInDepartment ?department2 .
  FILTER(?department1 != ?department2)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

