  ?publication coresr-ont:submittedBy ?author .
  ?author coresr-ont:advisedBy ?advisor .

  OPTIONAL {
    ?publication coresr-ont:associatedFieldOfStudy ?field .
  }

  ?author coresr-ont:nameAsString ?authorName.
  ?advisor coresr-ont:nameAsString ?advisorName.

}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?place ?attributeName WHERE {
  {
    SELECT ?place (GROUP_CONCAT(DISTINCT ?attributeName; separator=", ") AS ?attributes) WHERE {
      ?place a kwgl-ont:Place .
      OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?value . BIND("averageCoolingDegreeDaysPerMonth" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?value . BIND("averageHeatingDegreeDaysPerMonth" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?value . BIND("averageMonthlyTemperatureInCelsius" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?value . BIND("dollarDamageOfFiresImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?value . BIND("dollarDamageOfFloodsImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?value . BIND("dollarDamageOfHurricanesImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?value . BIND("dollarDamageOfLandslidesImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?value . BIND("dollarDamageOfStormSurgesImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?value . BIND("dollarDamageOfTornadoesImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:hasPopulation ?value . BIND("hasPopulation" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?value . BIND("maximumMonthlyTemperatureInCelsius" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?value . BIND("minimumMonthlyTemperatureInCelsius" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:numberOfEarthquakesImpactingPlace ?value . BIND("numberOfEarthquakesImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:numberOfFiresImpactingPlace ?value . BIND("numberOfFiresImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?value . BIND("numberOfFloodsImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?value . BIND("numberOfHurricanesImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:numberOfLandslidesImpactingPlace ?value . BIND("numberOfLandslidesImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?value . BIND("numberOfStormSurgesImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?value . BIND("numberOfTornadoesImpactingPlace" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?value . BIND("percentBelowPovertyLine" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:percentDiabetic ?value . BIND("percentDiabetic" AS ?attributeName) }
      OPTIONAL { ?place kwgl-ont:percentObese ?value . BIND("percentObese" AS ?attributeName) }
    } GROUP BY ?place
  }
  BIND(STRDT(?attributes, xsd:string) AS ?attributeName)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
