PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?hasHazardType ?dollarDamageOfFiresImpactingPlace ?dollarDamageOfFloodsImpactingPlace
?dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace ?dollarDamageOfStormSurgesImpactingPlace
?dollarDamageOfTornadoesImpactingPlace ?numberOfEarthquakesImpactingPlace ?numberOfFiresImpactingPlace
?numberOfFloodsImpactingPlace ?numberOfHurricanesImpactingPlace ?numberOfLandslidesImpactingPlace
?numberOfStormSurgesImpactingPlace ?numberOfTornadoesImpactingPlace ?affectedAreaInAcres ?damageToCropsInDollars
?damageToInfrastructureInDollars ?hasName ?hasStartDate ?hasEndDate

WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hasHazardType . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hasName . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?hasStartDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?hasEndDate . }

  ?place kwgl-ont:impactedBy ?hazardEvent .
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamageOfFiresImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfStormSurgesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace . }

  OPTIONAL { ?place kwgl-ont:numberOfEarthquakesImpactingPlace ?numberOfEarthquakesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:numberOfFiresImpactingPlace ?numberOfFiresImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?numberOfFloodsImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?numberOfHurricanesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:numberOfLandslidesImpactingPlace ?numberOfLandslidesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?numberOfStormSurgesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?numberOfTornadoesImpactingPlace . }

}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?damageDetail WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
              kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?damageDetail .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
SELECT DISTINCT ?place ?hazardAttribute ?damageImpact ?temporalData WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasHazardType kwglr:hurricane .
  ?place kwgl-ont:impactedBy ?hazardEvent .
  ?hazardEvent a kwgl-ont:Hurricane .

  # Retrieve hurricane-specific hazard attributes
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?numberOfHurricanes . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageAmount . }

  # Retrieve damage impact details and temporal data
  OPTIONAL {
    ?hazardEvent kwgl-ont:hasStartDate ?startDate .
    ?hazardEvent kwgl-ont:hasEndDate ?endDate .
    BIND(CONCAT("Damage Impact: ", COALESCE(?damageAmount, "N/A")) AS ?damageImpact)
  }

  # Bind the hazard attribute
  BIND(COALESCE(?numberOfHurricanes, "No data available") AS ?hazardAttribute)

  # Bind temporal data if available
  OPTIONAL { BIND(CONCAT("Start Date: ", COALESCE(?startDate, "N/A")) AS ?temporalData) }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
SELECT ?place ?damageDetail WHERE {
  ?hazardEvent a kwgl-ont:Tornado ;
              kwgl-ont:hasHazardType kwglr:tornado ;
              kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageDetail .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
SELECT ?hazardEvent ?place ?damageDetails WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
              kwgl-ont:hasImpacted ?place ;
              kwgl-ont:hasHazardType kwglr:hurricane .
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace2018 ?damageDetails . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2018 ?damageDetails . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?damageDetails . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace2018 ?damageDetails . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2018 ?damageDetails . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?damageDetails . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazardEvent ?type (GROUP_CONCAT(DISTINCT ?place; separator=", ") AS ?impactedPlaces) ?startDate ?endDate WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
               kwgl-ont:hasStartDate ?startDate ;
               kwgl-ont:hasEndDate ?endDate .
  OPTIONAL { ?hazardEvent kwgl-ont:hasImpacted ?place . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?type . }
}
GROUP BY ?hazardEvent ?type ?startDate ?endDate

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?place ?property ?value WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?value . }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?value . }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?value . }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?value . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:numberOfEarthquakesImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:numberOfFiresImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:numberOfLandslidesImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?value . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?value . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?value . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?value . }
  OPTIONAL { ?place kwgl-ont:percentObese ?value . }
  BIND(STR(?property) AS ?propertyName)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT DISTINCT ?place ?population ?households WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardType (COUNT(DISTINCT ?hazardEvent) AS ?count)
WHERE {
    ?hazardEvent a kwglr:Earthquake ;
                kwglr:hasHazardType ?hazardType .
}
GROUP BY ?hazardType

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT (COUNT(DISTINCT ?property) AS ?totalCount)
WHERE {
  {
    SELECT DISTINCT ?property
    WHERE {
      ?event rdf:type kwglr:tornado .
      ?property ?p ?o .
    }
    UNION
    {
      SELECT DISTINCT ?property
      WHERE {
        ?place rdf:type <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/Place> .
        ?place kwglr:impactedBy ?event .
        ?event rdf:type kwglr:tornado .
        ?property ?p ?o .
      }
    }
  }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?property ?label WHERE {
  {
    ?property rdfs:subPropertyOf* kwgl-ont:hasImpacted .
    ?property rdfs:label ?label .
  } UNION {
    ?property rdfs:subPropertyOf* kwgl-ont:impactedBy .
    ?property rdfs:label ?label .
  } UNION {
    ?property rdfs:subPropertyOf* kwgl-ont:dollarDamageOfStormSurgesImpactingPlace .
    ?property rdfs:label ?label .
  } UNION {
    ?property rdfs:subPropertyOf* kwgl-ont:dollarDamageOfTornadoesImpactingPlace .
    ?property rdfs:label ?label .
  }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?attribute
WHERE {
    { ?place a kwgl-ont:Place .
        OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?attribute . }
        OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?attribute . }
        OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?attribute . }
        OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?attribute . }
        OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?attribute . }
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?event ?type ?impactedPlace ?endDate ?startDate
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent ;
         kwgl-ont:hasStartDate ?startDate ;
         kwgl-ont:hasEndDate ?endDate .
  OPTIONAL { ?event kwgl-ont:hasHazardType ?type . }
  OPTIONAL {
    ?event kwgl-ont:hasImpacted ?impactedPlace .
    ?impactedPlace rdf:type kwgl-ont:Place ;
                   kwgl-ont:dollarDamageOfFiresImpactingPlace ?damage ;
                   kwgl-ont:numberOfDeaths ?deaths ;
                   kwgl-ont:numberOfEarthquakesImpactingPlace ?earthquakes ;
                   kwgl-ont:numberOfFiresImpactingPlace ?fires ;
                   kwgl-ont:numberOfFloodsImpactingPlace ?floods ;
                   kwgl-ont:numberOfHurricanesImpactingPlace ?hurricanes ;
                   kwgl-ont:numberOfLandslidesImpactingPlace ?landslides ;
                   kwgl-ont:numberOfStormSurgesImpactingPlace ?stormSurges ;
                   kwgl-ont:numberOfTornadoesImpactingPlace ?tornadoes .
  }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
SELECT DISTINCT ?damageToInfrastructureInDollars ?damageToCropsInDollars ?numberOfDeaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xml: <http://www.w3.org/XML/1998/namespace>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX terms: <http://purl.org/dc/terms/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?hazardAttribute ?damageImpact ?temporalData
WHERE {
    ?hurricane rdf:type kwglr:hurricane .
    ?hurricane ^kwgl-ont:hasHazardType ?hazardAttribute .

    OPTIONAL { ?hurricane kwgl-ont:hasImpacted ?place . }
    OPTIONAL { ?hurricane kwgl-ont:damageToCropsInDollars ?damageImpact .}
    OPTIONAL { ?hurricane kwgl-ont:damageToInfrastructureInDollars ?damageImpact .}
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageImpact .}
    OPTIONAL { ?place kwgl-ont:hasStartDate ?temporalData . }
    OPTIONAL { ?place kwgl-ont:hasEndDate ?temporalData . }

}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?damageToInfrastructureInDollars ?hasName
WHERE {
  ?HazardEvent a kwgl-ont:Hurricane ;
              kwgl-ont:hasImpacted ?Place ;
              kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars ;
              kwgl-ont:hasName ?hasName .
  ?Place rdfs:label ?hasName .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazard ?hazardType ?startDate ?endDate ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL {
    ?hazard kwgl-ont:hasHazardType ?hazardType .
  }
}
ORDER BY ?startDate

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?earthquake ?hazardTypeLabel ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?earthquake rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?earthquake kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazardType rdfs:label ?hazardTypeLabel . }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}
ORDER BY ?earthquake

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardEvent ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardEvent ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
}
ORDER BY ?hazardEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "hurricane")
  )
}
ORDER BY ?attribute

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?tornadoEvent ?placeName ?startDate ?endDate ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?tornadoEvent rdf:type kwgl-ont:Tornado .
  ?tornadoEvent kwgl-ont:hasHazardType kwglr:tornado .
  ?tornadoEvent kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?tornadoEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?tornadoEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?tornadoEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?tornadoEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }

  FILTER (?startDate >= "2018-01-01"^^xsd:date && ?endDate <= "2022-12-31"^^xsd:date)
}
ORDER BY ?tornadoEvent

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardEvent ?damageToCropsInDollars ?damageToInfrastructureInDollars ?affectedAreaInAcres ?numberOfDeaths ?startDate ?endDate ?placeName
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  ?hazardEvent kwgl-ont:hasHazardType kwglr:wildfire .
  ?hazardEvent kwgl-ont:impactedBy ?place .

  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }

  FILTER ( ?startDate >= "2021-01-01"^^xsd:date && ?endDate <= "2021-12-31"^^xsd:date )
}
ORDER BY ?hazardEvent

