  ?publication coress-ont:hasPublicationType ?publicationType .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?fieldOfStudy ?publication WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?title
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasTitle ?title .
  ?author a coress-ont:Author ;
          coress-ont:submits ?publication .
  ?department1 a coress-ont:Department ;
               coress-ont:hasAgent ?author .
  ?department2 a coress-ont:Department ;
               coress-ont:hasAgent ?author .
  FILTER (?department1 != ?department2)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName . }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard (GROUP_CONCAT(DISTINCT ?detail; separator=" | ") AS ?details) ?startDate
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard rdfs:label|kwgl-ont:hasName|^kwgl-ont:hasImpacted ?detail . }
  OPTIONAL { ?hazard a ?subClass . ?subClass rdfs:subClassOf* kwgl-ont:HazardEvent . FILTER(ISLITERAL(?subClass)) . BIND(?subClass AS ?detail) . }
}
GROUP BY ?hazard ?startDate

