PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?population ?numberOfHouseHolds
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL {?place kwgl-ont:hasPopulation ?population .}
  OPTIONAL {?place kwgl-ont:hasNumberOfHouseHolds ?numberOfHouseHolds .}
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>,
       xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardAttribute WHERE {
  { ?place a kwgl-ont:Place .
    ?place ?hazardAttribute ?value .
    FILTER (CONTAINS(STR(?hazardAttribute), "dollarDamageOfStormSurgesImpactingPlace") || CONTAINS(STR(?hazardAttribute), "numberOfHurricanesImpactingPlace") || CONTAINS(STR(?hazardAttribute), "numberOfFloodsImpactingPlace") || CONTAINS(STR(?hazardAttribute), "dollarDamageOfTornadoesImpactingPlace"))
  } UNION {
    ?event a kwgl-ont:Hurricane .
    ?place a kwgl-ont:Place .
    ?place kwgl-ont:hasImpacted ?event .
    ?event ?hazardAttribute ?value .
    FILTER (CONTAINS(STR(?hazardAttribute), "dollarDamageOfStormSurgesImpactingPlace") || CONTAINS(STR(?hazardAttribute), "numberOfHurricanesImpactingPlace") || CONTAINS(STR(?hazardAttribute), "numberOfFloodsImpactingPlace") || CONTAINS(STR(?hazardAttribute), "dollarDamageOfTornadoesImpactingPlace"))
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?floodAttribute ?place
WHERE {
  {
    ?place kwgl-ont:numberOfFloodsImpactingPlace ?value .
    BIND(CONCAT("Number of Floods Impacting Place: ", ?value) AS ?floodAttribute)
  } UNION {
    ?place kwgl-ont:numberOfFloodsImpactingPlace2018 ?value .
    BIND(CONCAT("Number of Floods Impacting Place in 2018: ", ?value) AS ?floodAttribute)
  } UNION {
    ?place kwgl-ont:numberOfFloodsImpactingPlace2019 ?value .
    BIND(CONCAT("Number of Floods Impacting Place in 2019: ", ?value) AS ?floodAttribute)
  } UNION {
    ?place kwgl-ont:numberOfFloodsImpactingPlace2020 ?value .
    BIND(CONCAT("Number of Floods Impacting Place in 2020: ", ?value) AS ?floodAttribute)
  } UNION {
    ?place kwgl-ont:numberOfFloodsImpactingPlace2021 ?value .
    BIND(CONCAT("Number of Floods Impacting Place in 2021: ", ?value) AS ?floodAttribute)
  } UNION {
    ?place kwgl-ont:numberOfFloodsImpactingPlace2022 ?value .
    BIND(CONCAT("Number of Floods Impacting Place in 2022: ", ?value) AS ?floodAttribute)
  } UNION {
    ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?value .
    BIND(CONCAT("Dollar Damage of Floods Impacting Place: $", ?value) AS ?floodAttribute)
  } UNION {
    ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2018 ?value .
    BIND(CONCAT("Dollar Damage of Floods Impacting Place in 2018: $", ?value) AS ?floodAttribute)
  } UNION {
    ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2019 ?value .
    BIND(CONCAT("Dollar Damage of Floods Impacting Place in 2019: $", ?value) AS ?floodAttribute)
  } UNION {
    ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2020 ?value .
    BIND(CONCAT("Dollar Damage of Floods Impacting Place in 2020: $", ?value) AS ?floodAttribute)
  } UNION {
    ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2021 ?value .
    BIND(CONCAT("Dollar Damage of Floods Impacting Place in 2021: $", ?value) AS ?floodAttribute)
  } UNION {
    ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2022 ?value .
    BIND(CONCAT("Dollar Damage of Floods Impacting Place in 2022: $", ?value) AS ?floodAttribute)
  }
}

