PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazard ?name ?type ?details WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasName ?name .
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard rdfs:label ?details . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardEvent ?dollarDamageOfFiresImpactingPlace ?dollarDamageOfFloodsImpactingPlace ?dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace ?dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamageOfFiresImpactingPlace . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfStormSurgesImpactingPlace . }
  OPTIONAL { ?hazardEvent kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hurricaneAttribute ?damageImpactDetail ?temporalData WHERE {
  { ?place kwgl-ont:hasHazardType kwglr:hurricane . }
  { ?place ?hurricaneAttribute ?value .
    FILTER (CONTAINS(STR(?hurricaneAttribute), "dollarDamageOf") ||
            CONTAINS(STR(?hurricaneAttribute), "numberOf")) } .
  OPTIONAL {
    ?place ?damageImpactDetail ?damageValue .
    FILTER (CONTAINS(STR(?damageImpactDetail), "DollarDamage") ||
            CONTAINS(STR(?damageImpactDetail), "NumberOf")) } .
  OPTIONAL { ?place kwgl-ont:hasStartDate ?temporalData . }
  UNION
  OPTIONAL { ?place kwgl-ont:hasEndDate ?temporalData . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?damageDetails
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
              kwgl-ont:hasImpacted ?place ;
              kwgl-ont:hasStartDate ?startDate ;
              kwgl-ont:hasEndDate ?endDate .

  FILTER ( ?startDate >= "2021-01-01"^^xsd:date && ?endDate <= "2021-12-31"^^xsd:date )

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?damageDetails . }
  UNION
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damageDetails . }
  UNION
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageDetails . }
  UNION
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?damageDetails . }
  UNION
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?damageDetails . }
  UNION
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageDetails . }

  FILTER (BOUND(?damageDetails))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard (GROUP_CONCAT(DISTINCT ?property; SEPARATOR=", ") AS ?details) ?startDate
WHERE {
  {
    SELECT DISTINCT ?hazard ?property WHERE {
      {
        ?hazard a kwgl-ont:Earthquake .
        ?hazard kwgl-ont:hasHazardType ?hazardType .
      } UNION {
        ?hazard a kwgl-ont:Fire .
        ?hazard kwgl-ont:hasHazardType ?hazardType .
      } UNION {
        ?hazard a kwgl-ont:Tornado .
        ?hazard kwgl-ont:hasHazardType ?hazardType .
      } UNION {
        ?hazard a kwgl-ont:Hurricane .
        ?hazard kwgl-ont:hasHazardType ?hazardType .
      }
    }
  }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL {
    { ?hazard kwgl-ont:numberOfDeaths ?value . BIND("Number of Deaths: " AS ?label) }
    UNION
    { ?hazard kwgl-ont:affectedAreaInAcres ?value . BIND("Affected Area in Acres: " AS ?label) }
    UNION
    { ?hazard kwgl-ont:damageToCropsInDollars ?value . BIND("Damage to Crops (USD): " AS ?label) }
    UNION
    { ?hazard kwgl-ont:damageToInfrastructureInDollars ?value . BIND("Damage to Infrastructure (USD): " AS ?label) }
  }
}
GROUP BY ?hazard ?startDate

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#> PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
SELECT ?place ?name
WHERE {
    ?place a kwgl-ont:Place .
    ?place kwgl-ont:hasName ?name .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?place ?hasPopulation ?hasNumberOfHouseHolds
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?hasPopulation . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?hasNumberOfHouseHolds . }
}

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?hazardType (COUNT(?hazardEvent) AS ?count)
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
              kwgl-ont:hasHazardType ?hazardType .
  ?hazardType rdfs:subClassOf* kwglr:earthquake .
}
GROUP BY ?hazardType

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?placeName ?hazardType ?dollarDamageOfFiresImpactingPlace ?numberOfEarthquakesImpactingPlace
       ?averageCoolingDegreeDaysPerMonth ?impactedByHazardEvent
WHERE {
  {?place a kwgl-ont:Place;
     kwgl-ont:hasName ?placeName.
    FILTER regex(?placeName, ".*", "i")
   }
   OPTIONAL{?hazardEvent kwgl-ont:hasImpacted ?place .
            ?hazardEvent kwgl-ont:hasHazardType ?hazardType}
  UNION
     {?place kwgl-ont:impactedBy ?hazardEvent .}
   OPTIONAL{?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamageOfFiresImpactingPlace .}
   OPTIONAL{?place kwgl-ont:numberOfEarthquakesImpactingPlace ?numberOfEarthquakesImpactingPlace .}
   OPTIONAL{?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?averageCoolingDegreeDaysPerMonth .
      FILTER regex(?averageCoolingDegreeDaysPerMonth, ".*", "i") }
} ORDER BY DESC(?impactedByHazardEvent)

PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?propertyName ?dataType WHERE {
  {{
    {
      SELECT DISTINCT ?propertyName ?dataType
      WHERE {
        ?Property rdfs:subClassOf* kwgl-ont:Place .
        ?Property a owl:DatatypeProperty ;
                 rdfs:domain kwgl-ont:Place ;
                 rdfs:range ?dataType .

        OPTIONAL { ?Property rdfs:label ?propertyName . }
      } FILTER (!bound(?propertyName))
    } UNION {
      SELECT DISTINCT ?propertyName ?dataType
      WHERE {
        ?Property rdfs:subClassOf* kwgl-ont:HazardEvent .
        ?Property a owl:DatatypeProperty ;
                 rdfs:domain kwgl-ont:HazardEvent ;
                 rdfs:range ?dataType .

        OPTIONAL { ?Property rdfs:label ?propertyName . }
      } FILTER (!bound(?propertyName))
    }
  } UNION {
     SELECT DISTINCT ?propertyName ?dataType
     WHERE {
       ?Property a owl:DatatypeProperty ;
                rdfs:domain kwgl-ont:Place ;
                rdfs:range ?dataType .

       OPTIONAL { ?Property rdfs:label ?propertyName . }
     } FILTER (!bound(?propertyName))
  } UNION {
     SELECT DISTINCT ?propertyName ?dataType
      WHERE {
        ?Property a owl:DatatypeProperty ;
                 rdfs:domain kwgl-ont:HazardEvent ;
                 rdfs:range ?dataType .

        OPTIONAL { ?Property rdfs:label ?propertyName . }
      } FILTER (!bound(?propertyName))
  }}
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?hasHazardType ?dollarDamageOfFiresImpactingPlace ?dollarDamageOfFloodsImpactingPlace
                       ?dollarDamageOfLandslidesImpactingPlace ?numberOfDeaths ?affectedAreaInAcres
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL {?hazardEvent kwgl-ont:hasHazardType ?hasHazardType .}
  OPTIONAL {?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?dollarDamageOfFiresImpactingPlace .}
  OPTIONAL {?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres .}
  OPTIONAL {?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths .}
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardEvent ?place ?dollarDamageOfFiresImpactingPlace ?dollarDamageOfFloodsImpactingPlace
       ?dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace
       ?dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace

WHERE {
  ?place kwgl-ont:impactedBy ?hazardEvent .
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamageOfFiresImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfStormSurgesImpactingPlace . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace . }

}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?damageDetail
WHERE {
  ?place a kwgl-ont:Place ;
         kwgl-ont:hasName ?placeName .
  ?hazardEvent a kwgl-ont:Hurricane, kwgl-ont:Tornado ;
               kwgl-ont:hasImpacted ?place ;
               kwgl-ont:damageToInfrastructureInDollars ?damageDetail ;
               kwgl-ont:hasStartDate ?startDate ;
               kwgl-ont:hasEndDate ?endDate .

  FILTER (xsd:date(?startDate) <= "2023-12-31"^^xsd:date && xsd:date(?endDate) >= "2023-01-01"^^xsd:date)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
