PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?agentName ?departmentName WHERE {
  ?agent coress-ont:hasFirstName ?firstName ;
         coress-ont:hasFamilyName ?familyName ;
         coress-ont:worksInDepartment ?department .
  ?department rdfs:label ?departmentName .
  BIND(CONCAT(?firstName, " ", ?familyName) AS ?agentName)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?fieldOfStudy ?publicationTitle WHERE {
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy ;
               coress-ont:hasTitle ?publicationTitle .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?publication ?title WHERE {
  ?publication a coress-ont:Publication ;
              coress-ont:hasTitle ?title .
  ?author1 a coress-ont:Author ;
           coress-ont:submits ?publication ;
           coress-ont:worksInDepartment ?dept1 .
  ?author2 a coress-ont:Author ;
           coress-ont:submits ?publication ;
           coress-ont:worksInDepartment ?dept2 .
  FILTER(?dept1 != ?dept2)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?authorName ?advisor ?fieldOfStudy WHERE {
  ?author a coress-ont:Author ;
          coress-ont:hasFirstName ?firstName ;
          coress-ont:hasFamilyName ?familyName ;
          coress-ont:advisedBy ?advisor .
  ?publication a coress-ont:Publication ;
               coress-ont:submittedBy ?author ;
               coress-ont:associatedFieldOfStudy ?fieldOfStudy .
  BIND(CONCAT(?firstName, " ", ?familyName) AS ?authorName)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

