  ?author coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?title
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasTitle ?title .
  ?author1 a coress-ont:Author ;
           coress-ont:submits ?publication ;
           coress-ont:worksInDepartment ?department1 .
  ?author2 a coress-ont:Author ;
           coress-ont:submits ?publication ;
           coress-ont:worksInDepartment ?department2 .
  FILTER(?department1 != ?department2)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?property WHERE {
  {
    SELECT ?property WHERE {
      ?property a owl:DatatypeProperty .
      FILTER(CONTAINS(STR(?property), "dollarDamageOfFiresImpactingPlace") ||
             CONTAINS(STR(?property), "numberOfFiresImpactingPlace") ||
             CONTAINS(STR(?property), "dollarDamageOfLandslidesImpactingPlace") ||
             CONTAINS(STR(?property), "numberOfLandslidesImpactingPlace") ||
             CONTAINS(STR(?property), "dollarDamageOfStormSurgesImpactingPlace") ||
             CONTAINS(STR(?property), "numberOfStormSurgesImpactingPlace"))
    }
  } UNION {
    SELECT ?property WHERE {
      ?property a owl:DatatypeProperty .
      FILTER(CONTAINS(STR(?property), "dollarDamageOfFloodsImpactingPlace") ||
             CONTAINS(STR(?property), "numberOfFloodsImpactingPlace"))
    }
  } UNION {
    SELECT ?property WHERE {
      ?property a owl:DatatypeProperty .
      FILTER(CONTAINS(STR(?property), "dollarDamageOfHurricanesImpactingPlace") ||
             CONTAINS(STR(?property), "numberOfHurricanesImpactingPlace"))
    }
  } UNION {
    SELECT ?property WHERE {
      ?property a owl:DatatypeProperty .
      FILTER(CONTAINS(STR(?property), "dollarDamageOfTornadoesImpactingPlace") ||
             CONTAINS(STR(?property), "numberOfTornadoesImpactingPlace"))
    }
  } UNION {
    SELECT ?property WHERE {
      ?property a owl:DatatypeProperty .
      FILTER(CONTAINS(STR(?property), "dollarDamageOfEarthquakesImpactingPlace") ||
             CONTAINS(STR(?property), "numberOfEarthquakesImpactingPlace"))
    }
  } UNION {
    SELECT ?property WHERE {
      ?property a owl:DatatypeProperty .
      FILTER(CONTAINS(STR(?property), "hasEndDate") ||
             CONTAINS(STR(?property), "hasStartDate"))
    }
  } UNION {
    SELECT ?property WHERE {
      ?property a owl:DatatypeProperty .
      FILTER(CONTAINS(STR(?property), "averageCoolingDegreeDaysPerMonth") ||
             CONTAINS(STR(?property), "averageHeatingDegreeDaysPerMonth") ||
             CONTAINS(STR(?property), "averageMonthlyTemperatureInCelsius") ||
             CONTAINS(STR(?property), "maximumMonthlyTemperatureInCelsius") ||
             CONTAINS(STR(?property), "minimumMonthlyTemperatureInCelsius"))
    }
  } UNION {
    SELECT ?property WHERE {
      ?property a owl:DatatypeProperty .
      FILTER(CONTAINS(STR(?property), "percentDiabetic") ||
             CONTAINS(STR(?property), "percentObese") ||
             CONTAINS(STR(?property), "hasPopulation"))
    }
  } UNION {
    SELECT ?property WHERE {
      ?property a owl:DatatypeProperty .
      FILTER(CONTAINS(STR(?property), "damageToCropsInDollars") ||
             CONTAINS(STR(?property), "damageToInfrastructureInDollars"))
    }
  } UNION {
    SELECT ?property WHERE {
      ?property a owl:DatatypeProperty .
      FILTER(CONTAINS(STR(?property), "hasName"))
    }
  } UNION {
    SELECT ?property WHERE {
      ?property a owl:ObjectProperty .
      FILTER(CONTAINS(STR(?property), "sfContains") ||
             CONTAINS(STR(?property), "sfIntersects") ||
             CONTAINS(STR(?property), "sfOverlaps") ||
             CONTAINS(STR(?property), "spatialRelation"))
    }
  } UNION {
    SELECT ?property WHERE {
      ?property a owl:ObjectProperty .
      FILTER(CONTAINS(STR(?property), "hasHazardType") ||
             CONTAINS(STR(?property), "impactedBy") ||
             CONTAINS(STR(?property), "isOfFireType"))
    }
  } UNION {
    SELECT ?property WHERE {
      ?property a owl:ObjectProperty .
      FILTER(CONTAINS(STR(?property), "hasPlaceType"))
    }
  }
}
ORDER BY ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?property WHERE {
  {
    ?property rdf:type owl:DatatypeProperty .
    FILTER (CONTAINS(STR(?property), "Population") || CONTAINS(STR(?property), "HouseHolds"))
  }
  UNION
  {
    ?property rdf:type owl:ObjectProperty .
    ?property rdfs:domain kwgl-ont:Place .
    ?property rdfs:range xsd:integer .
    FILTER (CONTAINS(STR(?property), "Population") || CONTAINS(STR(?property), "HouseHolds"))
  }
}
ORDER BY ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?property
WHERE {
  ?property rdf:type owl:DatatypeProperty .
  {
    SELECT DISTINCT ?subProperty WHERE {
      ?subProperty rdfs:subPropertyOf kwgl-ont:numberOfTornadoesImpactingPlace .
      FILTER CONTAINS(STR(?subProperty), "dollarDamage") || FILTER CONTAINS(STR(?subProperty), "numberOf")
    }
  } UNION
  {
    SELECT DISTINCT ?subProperty WHERE {
      ?subProperty rdfs:subPropertyOf kwgl-ont:numberOfFiresImpactingPlace .
      FILTER CONTAINS(STR(?subProperty), "dollarDamage") || FILTER CONTAINS(STR(?subProperty), "numberOf")
    }
  } UNION
  {
    SELECT DISTINCT ?subProperty WHERE {
      ?subProperty rdfs:subPropertyOf kwgl-ont:numberOfHurricanesImpactingPlace .
      FILTER CONTAINS(STR(?subProperty), "dollarDamage") || FILTER CONTAINS(STR(?subProperty), "numberOf")
    }
  } UNION
  {
    SELECT DISTINCT ?subProperty WHERE {
      ?subProperty rdfs:subPropertyOf kwgl-ont:numberOfEarthquakesImpactingPlace .
      FILTER CONTAINS(STR(?subProperty), "dollarDamage") || FILTER CONTAINS(STR(?subProperty), "numberOf")
    }
  } UNION
  {
    SELECT DISTINCT ?subProperty WHERE {
      ?subProperty rdfs:subPropertyOf kwgl-ont:numberOfFloodsImpactingPlace .
      FILTER CONTAINS(STR(?subProperty), "dollarDamage") || FILTER CONTAINS(STR(?subProperty), "numberOf")
    }
  } UNION
  {
    SELECT DISTINCT ?subProperty WHERE {
      ?subProperty rdfs:subPropertyOf kwgl-ont:numberOfLandslidesImpactingPlace .
      FILTER CONTAINS(STR(?subProperty), "dollarDamage") || FILTER CONTAINS(STR(?subProperty), "numberOf")
    }
  } UNION
  {
    SELECT DISTINCT ?subProperty WHERE {
      ?subProperty rdfs:subPropertyOf kwgl-ont:numberOfStormSurgesImpactingPlace .
      FILTER CONTAINS(STR(?subProperty), "dollarDamage") || FILTER CONTAINS(STR(?subProperty), "numberOf")
    }
  } UNION
  { SELECT DISTINCT ?subProperty WHERE {
      ?subProperty rdfs:subPropertyOf kwgl-ont:hasPopulation .
    }}
}
ORDER BY ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?attribute
WHERE {
  {
    SELECT DISTINCT ?attribute WHERE {
      ?attribute rdf:type owl:DatatypeProperty .
      FILTER (CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
              CONTAINS(LCASE(STR(?attribute)), "storm"))
    }
  } UNION {
    SELECT DISTINCT ?attribute WHERE {
      ?attribute rdfs:subPropertyOf kwgl-ont:numberOfHurricanesImpactingPlace .
    }
  } UNION {
    SELECT DISTINCT ?attribute WHERE {
      ?attribute rdfs:subPropertyOf kwgl-ont:dollarDamageOfStormSurgesImpactingPlace .
    }
  } UNION {
    SELECT DISTINCT ?attribute WHERE {
      ?attribute rdfs:subPropertyOf kwgl-ont:numberOfStormSurgesImpactingPlace .
    }
  }
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?property
WHERE {
  {
    ?property rdf:type owl:DatatypeProperty .
    FILTER (CONTAINS(LCASE(STR(?property)), "temperature") || CONTAINS(LCASE(STR(?property)), "average") || CONTAINS(LCASE(STR(?property)), "maximum") || CONTAINS(LCASE(STR(?property)), "minimum"))
  }
  UNION
  {
    ?property rdf:type owl:ObjectProperty .
    FILTER (CONTAINS(LCASE(STR(?property)), "temperature") || CONTAINS(LCASE(STR(?property)), "average") || CONTAINS(LCASE(STR(?property)), "maximum") || CONTAINS(LCASE(STR(?property)), "minimum"))
  }
}
ORDER BY ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?hazardEventType ?typeLabel
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent ;
              kwgl-ont:hasHazardType ?hazardType .
  OPTIONAL { ?hazardType rdfs:label ?typeLabel . }
}
ORDER BY ?hazardEventType

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?event ?hazardType ?dollarDamageOfFiresImpactingPlace
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL {
    ?place kwgl-ont:impactedBy ?event .
    ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamageOfFiresImpactingPlace .
  }
}
ORDER BY ?event

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hazardEvent ?propertyName ?value WHERE {
    { ?place kwgl-ont:impactedBy ?hazardEvent . }
    UNION
    { ?hazardEvent rdf:type kwgl-ont:Earthquake . }
    UNION
    { ?hazardEvent rdf:type kwgl-ont:Fire . }
    UNION
    { ?hazardEvent rdf:type kwgl-ont:Hurricane . }
    UNION
    { ?hazardEvent rdf:type kwgl-ont:Tornado . }

    {
        BIND("fire" AS ?propertyName)
        ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?value .
    } UNION {
        BIND("floods" AS ?propertyName)
        ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?value .
    } UNION {
        BIND("hurricanes" AS ?propertyName)
        ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?value .
    } UNION {
        BIND("landslides" AS ?propertyName)
        ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?value .
    } UNION {
        BIND("stormSurges" AS ?propertyName)
        ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?value .
    } UNION {
        BIND("tornadoes" AS ?propertyName)
        ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?value .
    }

    FILTER (
          ?hazardEvent rdf:type ?hazType
      && (?hazType = kwglr:fire || ?hazType = kwglr:wildfire)
    )
}

ORDER BY ?propertyName

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?attribute
  ?label
WHERE {
  {
    ?attribute rdf:type owl:DatatypeProperty .
    FILTER (CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
            CONTAINS(LCASE(STR(?attributeLabel)), "hurricane"))
  } UNION {
    ?event a kwgl-ont:Hurricane ;
           kwgl-ont:hasName ?label .
  }
}
ORDER BY ?attribute

PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?place ?tornadoEvent ?damageDetail
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?tornadoEvent rdf:type kwgl-ont:Tornado ;
              kwgl-ont:hasHazardType kwglr:tornado ;
              kwgl-ont:hasImpacted ?place .

  # Selecting all damage details related to tornadoes
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020 ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021 ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 ?damageDetail . }

  # Optional temporal extent filter (uncomment and modify as needed)
  # OPTIONAL { ?tornadoEvent kwgl-ont:hasStartDate ?startDate .
  #           FILTER (?startDate >= "2021-01-01"^^xsd:date && ?startDate <= "2022-12-31"^^xsd:date) . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazardEvent ?damageDetail ?place ?startDate ?endDate
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Hurricane .
  ?hazardEvent kwgl-ont:hasImpacted ?place .
  ?hazardEvent kwgl-ont:hasStartDate ?startDate .
  ?hazardEvent kwgl-ont:hasEndDate ?endDate .

  # Damage details
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?damageDetail .
              FILTER(?startDate >= "2018-01-01"^^xsd:date && ?endDate <= "2018-12-31"^^xsd:date) . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?damageDetail .
              FILTER(?startDate >= "2019-01-01"^^xsd:date && ?endDate <= "2019-12-31"^^xsd:date) . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?damageDetail .
              FILTER(?startDate >= "2020-01-01"^^xsd:date && ?endDate <= "2020-12-31"^^xsd:date) . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?damageDetail .
              FILTER(?startDate >= "2021-01-01"^^xsd:date && ?endDate <= "2021-12-31"^^xsd:date) . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?damageDetail .
              FILTER(?startDate >= "2022-01-01"^^xsd:date && ?endDate <= "2022-12-31"^^xsd:date) . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?damageDetail . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?name WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place rdfs:label ?name . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?geographicalPlace ?healthRelatedConcernOrAttribute
WHERE {
  {  # Health-related concerns or attributes related to AdministrativeRegion
    ?geographicalPlace rdf:type kwg-ont:AdministrativeRegion .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to Hazard
    ?geographicalPlace rdf:type kwg-ont:Hazard .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to NOAAHazardEvent
    ?geographicalPlace rdf:type kwg-ont:NOAAHazardEvent .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to Hospital
    ?geographicalPlace rdf:type kwg-ont:Hospital .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to NOAAHazard
    ?geographicalPlace rdf:type kwg-ont:NOAAHazard .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to NOAADrought
    ?geographicalPlace rdf:type kwg-ont:NOAADrought .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to NIFCFire
    ?geographicalPlace rdf:type kwg-ont:NIFCFire .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to Earthquake
    ?geographicalPlace rdf:type kwg-ont:Earthquake .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to AirQualitySite
    ?geographicalPlace rdf:type kwg-ont:AirQualitySite .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to FEMADisaster
    ?geographicalPlace rdf:type kwg-ont:FEMADisaster .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to MTBSFire
    ?geographicalPlace rdf:type kwg-ont:MTBSFire .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to SoilMapUnit
    ?geographicalPlace rdf:type kwg-ont:SoilMapUnit .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to USClimateDivision
    ?geographicalPlace rdf:type kwg-ont:USClimateDivision .
    OPTIONAL { ?geographicalPlace sosa:observedProperty ?healthRelatedConcernOrAttribute . }
    OPTIONAL { ?geographicalPlace sosa:hasSimpleResult ?healthRelatedConcernOrAttribute . }
  } UNION {
    # Health-related concerns or attributes related to PublicHealthObservation
    ?publicHealthObservation rdf:type kwg-ont:PublicHealthObservation .
    ?publicHealthObservation sosa:observedProperty ?healthRelatedConcernOrAttribute .
    ?publicHealthObservation sosa:hasFeatureOfInterest ?geographicalPlace .
  } UNION {
    # Health-related concerns or attributes related to ImpactObservation
    ?impactObservation rdf:type kwg-ont:ImpactObservation .
    ?impactObservation sosa:observedProperty ?healthRelatedConcernOrAttribute .
    ?impactObservation sosa:hasFeatureOfInterest ?geographicalPlace .
  } UNION {
    # Health-related concerns or attributes related to VulnerabilityObservation
    ?vulnerabilityObservation rdf:type kwg-ont:VulnerabilityObservation .
    ?vulnerabilityObservation sosa:observedProperty ?healthRelatedConcernOrAttribute .
    ?vulnerabilityObservation sosa:hasFeatureOfInterest ?geographicalPlace .
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazardAttribute ?attributeValue
WHERE {
  ?place a geo:Feature .
  ?place geo:hasGeometry|geo:hasDefaultGeometry ?geometry .

  OPTIONAL {
    ?hazard a kwg-ont:NOAAHazardEvent .
    FILTER(?hazard = kwg-ont:NOAAFlood) .
    ?hazard rdfs:subClassOf* ?hazardType .
    BIND(CONCAT(STR(?hazardType), " (Flood Hazard Type)") AS ?hazardAttribute) .
    OPTIONAL { ?hazard ?property ?value . BIND(CONCAT(STR(?property), ": ", STR(?value)) AS ?attributeValue) }
  }

  UNION

  OPTIONAL {
    ?place kwg-ont:spatialRelation ?cell .
    ?cell a kwg-ont:Cell .
    ?hazard a kwg-ont:NOAAHazardEvent .
    FILTER(?hazard = kwg-ont:NOAAFlood) .
    ?hazard rdfs:subClassOf* ?hazardType .
    BIND(CONCAT(STR(?hazardType), " (Flood Hazard Type in Cell)") AS ?hazardAttribute) .
    OPTIONAL { ?hazard ?property ?value . BIND(CONCAT(STR(?property), ": ", STR(?value)) AS ?attributeValue) }
  }

  UNION

  OPTIONAL {
    ?place kwg-ont:spatialRelation ?admRegion .
    ?admRegion a kwg-ont:AdministrativeRegion .
    ?hazard a kwg-ont:NOAAHazardEvent .
    FILTER(?hazard = kwg-ont:NOAAFlood) .
    ?hazard rdfs:subClassOf* ?hazardType .
    BIND(CONCAT(STR(?hazardType), " (Flood Hazard Type in Administrative Region)") AS ?hazardAttribute) .
    OPTIONAL { ?hazard ?property ?value . BIND(CONCAT(STR(?property), ": ", STR(?value)) AS ?attributeValue) }
  }

  UNION

  OPTIONAL {
    ?place geo:hasGeometry|geo:hasDefaultGeometry ?geometry .
    ?hazard a kwg-ont:NOAAHazardEvent .
    FILTER(?hazard = kwg-ont:NOAAFlood) .
    ?hazard rdfs:subClassOf* ?hazardType .
    BIND(CONCAT(STR(?hazardType), " (Flood Hazard Type with Geometry)") AS ?hazardAttribute) .
    OPTIONAL { ?hazard ?property ?value . BIND(CONCAT(STR(?property), ": ", STR(?value)) AS ?attributeValue) }
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeHazard ?hazardType ?property ?value
WHERE {
  ?earthquakeHazard rdfs:subClassOf* kwg-ont:Earthquake .
  BIND(kwg-ont:Earthquake AS ?hazardType) .
  OPTIONAL { ?earthquakeHazard ?property ?value . }
}
ORDER BY ?earthquakeHazard ?property

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?hazardAttribute ?damageImpactDetail ?temporalData WHERE {
  {
    ?hazard a kwg-ont:NOAAHurricane .
    ?hazard rdfs:subClassOf* ?hazardType .
    ?hazard geo:hasGeometry/geo:asWKT ?geometry .
    FILTER(CONTAINS(ST_GEOMFROMTEXT(?geometry), ?placeGeometry))
  } UNION {
    ?damageImpact a kwg-ont:DamageObservation .
    ?damageImpact sosa:observedProperty ?impactType .
    ?damageImpact sosa:hasSimpleResult ?damageValue .
  } UNION {
    ?temporalData a time:TemporalEntity .
    ?hazard kwg-ont:hasTemporalScope ?temporalData .
    OPTIONAL { ?temporalData time:inXSDDateTime ?dateTime . }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazardEvent ?hazardType ?startDate ?endDate
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
}
ORDER BY ?hazardEvent

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?place ?attribute ?value
WHERE {
  ?place rdf:type kwgl-ont:Place .
  {
    SELECT ?attribute WHERE {
      ?attribute a owl:DatatypeProperty ;
                rdfs:domain kwgl-ont:Place .
    }
  }
  OPTIONAL { ?place ?attribute ?value . }
}
ORDER BY ?place ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?attribute
WHERE {
  {
    SELECT DISTINCT ?attribute WHERE {
      ?attribute rdf:type owl:DatatypeProperty .
      FILTER (
        CONTAINS(LCASE(STR(?attribute)), "population") ||
        CONTAINS(LCASE(STR(?attribute)), "household")
      )
    }
  } UNION {
    SELECT DISTINCT ?attribute WHERE {
      ?attribute rdf:type owl:ObjectProperty .
      FILTER (
        CONTAINS(LCASE(STR(?attribute)), "placeType") ||
        CONTAINS(LCASE(STR(?attribute)), "spatialRelation")
      )
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
WHERE {
  {
    SELECT DISTINCT ?attribute WHERE {
      ?attribute rdf:type owl:DatatypeProperty .
      FILTER (
        CONTAINS(LCASE(STR(?attribute)), "storm") ||
        CONTAINS(LCASE(STR(?attribute)), "hurricane")
      )
    }
  }

  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazardEvent ?hazardTypeLabel ?affectedAreaInAcres
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?hazardType rdfs:label ?hazardTypeLabel . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?place ?hazardType ?damageDetail
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:impactedBy ?hazardEvent .
  ?hazardEvent a kwgl-ont:HazardEvent ;
              kwgl-ont:hasHazardType ?hazardType .

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageDetail . }

  FILTER (BOUND(?hazardType) && BOUND(?damageDetail))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "hurricane")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?placeName ?damageDetail
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Tornado .
  ?hazardEvent kwgl-ont:hasHazardType kwglr:tornado .
  ?hazardEvent kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020 ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021 ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 ?damageDetail . }

  ?place kwgl-ont:hasName ?placeName .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?place ?hazardEvent ?damageDetail ?temporalExtent
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?place kwgl-ont:hasImpacted ?hazardEvent .
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  ?hazardEvent kwgl-ont:hasHazardType kwglr:hurricane .

  # Damage details for storm-specific hazards (hurricanes)
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2018 ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2019 ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2020 ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2021 ?damageDetail . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2022 ?damageDetail . }

  # Temporal extent
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?temporalExtent . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?temporalExtent . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author
WHERE {
  ?author rdf:type coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doi
WHERE {
  ?publication coresr-ont:hasIdentifier ?doi .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department
WHERE {
  ?department rdf:type coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?title ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication ;
               coresr-ont:hasTitle ?title ;
               coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?type
WHERE {
  ?publication coresr-ont:hasPublicationType ?type .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?title ?fieldOfStudy
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
  ?publication coresr-ont:hasTitle ?title .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS { ?agent coresr-ont:hasContactInformation ?contactInfo . ?contactInfo a coresr-ont:FamilyName }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?author WHERE {
  ?author a coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publicationTitle ?doi WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasTitle ?publicationTitle ;
               coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department WHERE {
  ?department a coress-ont:Department.
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?submissionDate WHERE {
    ?publication coress-ont:dateOfSubmission ?submissionDate.
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?authorName ?advisorName WHERE {
  ?author a coress-ont:Author ;
          coress-ont:hasFirstName ?firstName ;
          coress-ont:hasFamilyName ?familyName .
  BIND(CONCAT(?firstName, " ", ?familyName) AS ?authorName)
  ?author coress-ont:advisedBy ?advisorString .
  ?advisor a coress-ont:Agent ;
           coress-ont:hasFirstName ?advFirstName ;
           coress-ont:hasFamilyName ?advFamilyName .
  BIND(CONCAT(?advFirstName, " ", ?advFamilyName) AS ?advisorName)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?publicationType WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?publicationType .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?agent ?department WHERE {
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?fieldOfStudy ?publicationTitle
WHERE {
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy ;
               coress-ont:hasTitle ?publicationTitle .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?author ?advisor ?field ?title WHERE {
  ?author a coress-ont:Author ;
          coress-ont:advisedBy ?advisor ;
          coress-ont:submits ?publication .

  ?publication coress-ont:hasTitle ?title .
  OPTIONAL {
    ?publication coress-ont:associatedFieldOfStudy ?field .
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department (COUNT(?agent) AS ?count)
WHERE {
  ?department coress-ont:hasAgent ?agent .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?familyName }
}
GROUP BY ?department
ORDER BY DESC(?count)

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardType ?property ?value ?temporalScope
WHERE {
  ?hazard rdfs:subClassOf* kwg-ont:Hazard .
  BIND(REPLACE(STR(?hazard), "http://stko-kwg.geog.ucsb.edu/lod/ontology/", "") AS ?hazardType) .
  OPTIONAL { ?hazard ?property ?value . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . }
}
ORDER BY ?hazardType ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place rdfs:label ?name . }
}
ORDER BY ?place

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?healthConcern
WHERE {
  ?place rdfs:subClassOf* kwg-ont:AdministrativeRegion .
  OPTIONAL { ?place kwg-ont:spatialRelation ?hazard . }
  OPTIONAL { ?hazard rdfs:subClassOf* kwg-ont:Hazard . }
  BIND(COALESCE(?hazard, ?place) AS ?healthConcern)
}
ORDER BY ?place

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazardAttribute ?property ?value
WHERE {
  ?hazardType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?hazardType ?property ?value . }
  BIND(?hazardType AS ?hazardAttribute)
}
ORDER BY ?hazardAttribute ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazardAttribute ?property ?value
WHERE {
  ?hazardType rdfs:subClassOf* kwg-ont:NOAAFlood .
  OPTIONAL { ?hazardType ?property ?value . }
  BIND(?hazardType AS ?hazardAttribute)
}
ORDER BY ?hazardAttribute ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeHazard ?hazardType ?property ?value
WHERE {
  ?earthquakeHazard rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeHazard rdfs:subClassOf ?hazardType . }
  OPTIONAL { ?earthquakeHazard ?property ?value . }
}
ORDER BY ?earthquakeHazard ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazardEvent ?impactProperty ?value
WHERE {
  ?hazardEvent rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?hazardEvent sosa:hasFeatureOfInterest ?impactObservation . }
  OPTIONAL { ?impactObservation sosa:observedProperty ?impactProperty . }
  OPTIONAL { ?impactObservation sosa:hasSimpleResult ?value . }
}
ORDER BY ?hazardEvent ?impactProperty

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazardAttribute ?damageImpactDetail ?temporalData
WHERE {
  kwg-ont:NOAAHurricane rdfs:subClassOf* ?hazardType .
  ?hazardType rdfs:subClassOf kwg-ont:Hazard .

  OPTIONAL { ?hazardType ?property ?hazardAttribute . }

  kwg-ont:ImpactObservation sosa:observedProperty ?impactObservableProperty .
  OPTIONAL {
    ?impactObservableProperty rdfs:subClassOf* ?impactType .
    ?impactType rdfs:label ?damageImpactDetail .
  }

  OPTIONAL { kwg-ont:NOAAHurricane time:hasBeginning ?temporalData . }
  OPTIONAL { kwg-ont:NOAAHurricane time:hasEnd ?temporalData . }
}
ORDER BY ?hazardAttribute ?damageImpactDetail

PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?damageDetail
WHERE {
  kwg-ont:NOAATornado rdfs:subClassOf kwg-ont:Hazard .
  kwg-ont:NOAATornado geo:hasGeometry ?geometry .
  ?hazardEvent a kwg-ont:NOAAHazardEvent ;
              geo:hasGeometry ?geometry ;
              sosa:observedProperty ?observableProperty ;
              time:hasTemporalScope ?temporalExtent .

  OPTIONAL { ?observableProperty rdfs:subClassOf* kwgr:magnitudeObservableProperty.* .
             ?hazardEvent sosa:observedProperty ?observableProperty .
             ?hazardEvent sosa:hasSimpleResult ?damageDetail . }

}
ORDER BY ?damageDetail

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?hazardType ?details ?time
WHERE {
  {
    ?hazard rdf:type kwg-ont:Hazard .
    ?hazard rdfs:label ?hazardType .
    OPTIONAL { ?hazard geo:hasDefaultGeometry ?geometry . }
    OPTIONAL { ?hazard time:hasTime ?time . }
    OPTIONAL {
      ?hazard a kwg-ont:Earthquake ;
              sosa:observedProperty ?observableProperty .
      ?observableProperty rdfs:label ?details .
    } UNION
    OPTIONAL {
      ?hazard a kwg-ont:DroughtZone ;
              kwg-ont:hasTemporalScope ?temporalEntity .
      ?temporalEntity time:inXSDDateTime ?time .
    } UNION
    OPTIONAL {
      ?hazard a kwg-ont:Fire ;
              kwg-ont:hasFireCause ?fireCause .
      ?fireCause rdfs:label ?details .
    } UNION
    OPTIONAL {
      ?hazard a kwg-ont:NOAAHazardEvent ;
              kwg-ont:hasSegment ?eventSegment .
      ?eventSegment kwg-ont:startsFrom ?fix .
      ?fix geo:hasDefaultGeometry ?geometry .
    }
  } UNION
  {
    ?hazard rdf:type kwg-ont:SmokePlumeSnapshot .
    OPTIONAL { ?hazard time:hasTime ?time . }
    OPTIONAL { ?hazard geo:hasDefaultGeometry ?geometry . }
    OPTIONAL {
      ?hazard sosa:observedProperty ?observableProperty .
      ?observableProperty rdfs:label ?details .
    }
  } UNION
  {
    ?hazard rdf:type kwg-ont:FEMADisaster ;
            kwg-ont:hasDeclaration ?declaration .
    OPTIONAL { ?declaration time:hasTime ?time . }
    OPTIONAL { ?declaration kwg-ont:designatedArea ?details . }
  } UNION
  {
    ?hazard rdf:type kwg-ont:BlueskyModeledWildfire ;
            geo:hasDefaultGeometry ?geometry .
    OPTIONAL { ?hazard time:hasTime ?time . }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?place ?name WHERE {
  {
    ?place rdfs:subClassOf* geo:Feature .
    ?place rdfs:label ?name .
  } UNION {
    ?place rdf:type usgs:Terrain .
    ?place rdfs:label ?name .
  } UNION {
    ?place rdf:type usgs:SurfaceWater .
    ?place rdfs:label ?name .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?healthConcern WHERE {
  {
    ?place a kwg-ont:Hospital .
    ?place kwg-ont:hospitalType ?hospitalType .
    ?hospitalType rdfs:label ?healthConcern .
  } UNION {
    ?place a kwg-ont:PublicHealthDepartment .
    ?place kwg-ont:publicHealthDepartmentName ?healthConcern .
  } UNION {
    ?place a kwg-ont:Pharmacy .
    ?place kwg-ont:pharmacyType ?pharmacyType .
    ?pharmacyType rdfs:label ?healthConcern .
  }
}

