PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardAttribute ?attributeDetails
WHERE {
  {
    SELECT ?hazardAttribute (GROUP_CONCAT(DISTINCT ?attributeDetails; separator=" | ") AS ?details) WHERE {
      {
        # Storm-specific hazard attributes related to geographical places
        ?stormHazard a kwg-ont:NOAAHazardEvent ;
                    rdfs:label ?hazardAttribute .
        OPTIONAL { ?stormHazard sosa:observedProperty ?observableProperty . }
        OPTIONAL { ?stormHazard sosa:hasFeatureOfInterest ?featureOfInterest . }
        OPTIONAL { ?stormHazard geo:hasGeometry ?geometry . }
        OPTIONAL { ?stormHazard kwg-ont:spatialRelation ?spatialRelation . }

        # Get details about the observable properties
        OPTIONAL {
          ?observableProperty rdfs:subClassOf* ?observableType .
          BIND(CONCAT("Observable Property Type: ", STR(?observableType)) AS ?attributeDetails)
        }

        # Get details about the feature of interest
        OPTIONAL {
          ?featureOfInterest a ?featureType ;
                            geo:hasGeometry ?geometry .
          BIND(CONCAT("Feature of Interest Type: ", STR(?featureType), " | Geometry: ", STR(?geometry)) AS ?attributeDetails)
        }

        # Get details about the spatial relation
        OPTIONAL {
          ?spatialRelation a ?relationType ;
                          kwg-ont:hasGeometry ?relationGeometry .
          BIND(CONCAT("Spatial Relation Type: ", STR(?relationType), " | Geometry: ", STR(?relationGeometry)) AS ?attributeDetails)
        }
      }
    } GROUP BY ?hazardAttribute
  }

  UNION

  {
