PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardAttribute ?hazardAttributeLabel WHERE {
  {
    SELECT ?hazardAttribute ?hazardAttributeLabel WHERE {
      {
        ?hazard a kwg-ont:Hazard .
        ?hazard rdfs:subClassOf* ?hazardType .
        ?hazardType rdfs:label ?hazardAttributeLabel .
        FILTER (STRSTARTS(STR(?hazard), "http://www.kgw.org/ontology#NOAA"))
      } UNION {
        ?hazard a kwg-ont:Hazard .
        ?hazard rdfs:subClassOf* ?hazardType .
        ?hazardType rdfs:label ?hazardAttributeLabel .
        FILTER (STRSTARTS(STR(?hazard), "http://www.kgw.org/ontology#Earthquake"))
      } UNION {
        ?hazard a kwg-ont:Hazard .
        ?hazard rdfs:subClassOf* ?hazardType .
        ?hazardType rdfs:label ?hazardAttributeLabel .
        FILTER (STRSTARTS(STR(?hazard), "http://www.kgw.org/ontology#Drought"))
      } UNION {
        ?hazard a kwg-ont:Hazard .
        ?hazard rdfs:subClassOf* ?hazardType .
        ?hazardType rdfs:label ?hazardAttributeLabel .
        FILTER (STRSTARTS(STR(?hazard), "http://www.kgw.org/ontology#Fire"))
      } UNION {
        ?hazard a kwg-ont:Hazard .
        ?hazard rdfs:subClassOf* ?hazardType .
        ?hazardType rdfs:label ?hazardAttributeLabel .
        FILTER (STRSTARTS(STR(?hazard), "http://www.kgw.org/ontology#Smoke"))
      }
    }
  } UNION {
    SELECT ?hazardAttribute ?hazardAttributeLabel WHERE {
      {
        ?observationProperty a sosa:ObservableProperty ;
                          rdfs:subClassOf* ?observableType .
        ?observableType rdfs:label ?hazardAttributeLabel .
        FILTER (STRSTARTS(STR(?observationProperty), "http://www.kgw.org/ontology#NOAA"))
      } UNION {
        ?observationProperty a sosa:ObservableProperty ;
                          rdfs:subClassOf* ?observableType .
        ?observableType rdfs:label ?hazardAttributeLabel .
        FILTER (STRSTARTS(STR(?observationProperty), "http://www.kgw.org/ontology#Earthquake"))
      } UNION {
        ?observationProperty a sosa:ObservableProperty ;
                          rdfs:subClassOf* ?observableType .
        ?observableType rdfs:label ?hazardAttributeLabel .
        FILTER (STRSTARTS(STR(?observationProperty), "http://www.kgw.org/ontology#Drought"))
