PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?attribute WHERE {
  {
    SELECT DISTINCT ?attribute WHERE {
      ?place a kwg-ont:AdministrativeRegion .
      ?place kwg-ont:spatialRelation ?cell .
      ?cell a kwg-ont:S2Cell .
      ?cell geo:hasGeometry ?geometry .
      ?geometry geo:asWKT ?wkt .

      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:ClimateObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:CensusObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:CroplandObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:DroughtIntensity . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:EarthquakeObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:ImpactObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:MagnitudeObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:MTBSFireObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:NIFCFireObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:PublicHealthObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:SmokePlumeObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:SoilMapUnitObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:StormTrackObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:StormTrackletObservableProperty . }
      OPTIONAL { ?attribute rdfs:subClassOf kwg-ont:VulnerabilityObservableProperty . }

    } GROUP BY ?attribute
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?hazardType ?hazardDetails WHERE {
  ?hazard rdf:type kwg-ont:Hazard .
  ?hazard rdfs:label ?hazardType .
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope . }
  OPTIONAL { ?hazard geo:hasGeometry ?geometry . }
  OPTIONAL { ?hazard geo:hasDefaultGeometry ?defaultGeometry . }
  BIND(GROUP_CONCAT(DISTINCT ?property ; separator=", ") AS ?hazardDetails) WHERE {
    ?hazard sosa:observedProperty ?observableProperty .
    ?observableProperty rdfs:label ?property .
  } .
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?damageDetails WHERE {
    ?hazard a kwg-ont:Hazard ;
            kwg-ont:spatialRelation ?region .
    ?damageDetails a kwg-ont:ImpactObservableProperty ;
                   rdfs:subClassOf* ?impactType .
    ?observation a sosa:Observation ;
                 sosa:hasFeatureOfInterest ?hazard ;
                 sosa:observedProperty ?damageDetails .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardAttribute ?damageImpactDetail ?temporalData
WHERE {
  {
    SELECT ?hazardAttribute WHERE {
      ?hazard kwg-ont:spatialRelation ?geographicalPlace .
      ?hazard a kwg-ont:NOAAHurricane ;
              kwg-ont:hasPart ?hazardEvent .
      ?hazardEvent a kwg-ont:NOAAHazardEvent ;
                  sosa:isFeatureOfInterestOf ?observationCollection .
      ?observationCollection a kwg-ont:ImpactObservationCollection ;
                            sosa:hasMember ?impactObservation .
      ?impactObservation sosa:observedProperty ?hazardAttribute .
    }
  } UNION {
    SELECT ?damageImpactDetail WHERE {
      ?hazardEvent a kwg-ont:NOAAHazardEvent ;
                  sosa:isFeatureOfInterestOf ?impactObservationCollection .
      ?impactObservationCollection a kwg-ont:ImpactObservationCollection ;
                                 sosa:hasMember ?impactObservation .
      ?impactObservation sosa:observedProperty ?damageImpactDetail ;
                        sosa:hasSimpleResult ?result .
    }
  } UNION {
    SELECT ?temporalData WHERE {
      ?hazardEvent a kwg-ont:NOAAHazardEvent ;
                  sosa:isFeatureOfInterestOf ?impactObservationCollection .
      ?impactObservationCollection a kwg-ont:ImpactObservationCollection ;
                                 sosa:phenomenonTime ?temporalData .
    }
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?damageDetails WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          rdfs:label "Tornado" .
  ?hazard sosa:hasFeatureOfInterest ?feature .
  ?feature geo:hasGeometry ?geometry .
  ?hazard kwg-ont:spatialRelation ?geographicalPlace .
  ?geographicalPlace a kwg-ont:AdministrativeRegion ;
                     geo:hasDefaultGeometry ?geometry .
  ?hazard kwg-ont:hasTemporalScope ?temporalExtent .
  ?impactObservation sosa:observedProperty ?impactObservableProperty ;
                     sosa:phenomenonTime ?temporalExtent ;
                     sosa:hasFeatureOfInterest ?feature .
  ?impactObservableProperty rdfs:subClassOf kwg-ont:ImpactObservableProperty .
  ?damageDetails a kwg-ont:ImpactObservation ;
                 sosa:observedProperty ?impactObservableProperty ;
                 sosa:phenomenonTime ?temporalExtent ;
                 sosa:hasFeatureOfInterest ?feature .
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?damageDetails WHERE {
  ?hazard a kwg-ont:NOAAHazardEvent ;
          kwg-ont:spatialRelation ?place .
  ?place a geo:Feature ;
         geo:hasGeometry ?geometry .
  ?observation sosa:observedProperty ?observableProperty ;
               sosa:hasFeatureOfInterest ?hazard ;
               sosa:phenomenonTime ?temporalExtent .
  ?damageDetails sosa:hasSimpleResult ?result .
}
